INSERT INTO milestone_windows (
  slug, title, category, urgency,
  open_age_weeks, peak_age_weeks, close_age_weeks,
  priority, why_it_matters, what_to_do,
  what_not_to_worry, missed_window, source_citation,
  playbook_link, prenatal, active
) VALUES
  ('cognitive-animals-sounds', 'Names animals and their sounds', 'cognitive', 'advisory',
   65, 78, 104,
   3, 'Animal names and sounds are among the earliest vocabulary items children acquire because they are acoustically distinctive and emotionally engaging. Naming animals and their sounds builds vocabulary, categorization skills, and the ability to recall and produce learned associations. It is also a standard item on many early language screens.', '* Name animals in books, at the park, in real life: "that is a dog. The dog says woof."
* Use animal sounds playfully in conversation and songs
* Animal matching games and puzzles extend this vocabulary naturally',
   'Children often learn the animal sound before the animal name, "woof" before "dog." Both count as communication and vocabulary development.', 'If your 18 month old cannot associate any animal with its name or sound, mention it at the 18 month visit as part of receptive vocabulary review.', 'CDC; Fenson et al. (1994), MacArthur Communicative Development Inventories',
   NULL, FALSE, TRUE),
  ('cognitive-attention-span', 'Build attention span — short, focused play sessions', 'cognitive', 'advisory',
   0, 52, 156,
   3, 'Attention span in early childhood is largely shaped by experience. Research by Ruff and Rothbart shows that sustained, focused play with a single activity builds attentional capacity over time. The child who is constantly moved from one activity to the next never develops the ability to concentrate deeply. Background screens are the most studied disruptor of sustained attention in young children.', '* Do not interrupt sustained play, if a child is engaged with a toy for 10 minutes, let them finish
* Offer fewer choices at once: one or two toys, not a room full
* Reduce background noise and screen time during play periods',
   'Normal attention spans at various ages: 3 to 5 minutes at age 1; 5 to 10 minutes at age 2; 10 to 15 minutes at age 3. These are for self chosen activities, not structured tasks.', 'If your 2 year old cannot focus on any single activity for more than 1 to 2 minutes, mention it at the 24 month visit.', 'Ruff and Rothbart (1996), Attention in Early Development; AAP Screen Time',
   NULL, FALSE, TRUE),
  ('cognitive-big-little', 'Concept of size — big/little', 'cognitive', 'advisory',
   91, 104, 130,
   3, 'Size comparison (big and little, more and less, long and short) is an early mathematical concept. It emerges around 21 to 27 months through repeated comparison and labeling. It is a foundational concept for measurement, quantity, and early numeracy.', '* Compare sizes explicitly in daily life: "this is the big spoon. That is the little spoon."
* Sort objects by size and narrate: "the big blocks go here, the little blocks go there"
* Books with size contrasts (like The Very Hungry Caterpillar or Goldilocks) embed this naturally',
   'Children at this age will frequently get big and little reversed, especially when applied to unfamiliar objects. Consistent modeling corrects this over time.', 'If your 30 month old has no concept of relative size at all, mention it at the 30 month visit.', 'CDC; Mix et al. (2002), Mathematical Cognition in Early Childhood',
   NULL, FALSE, TRUE),
  ('cognitive-block-play', 'Block / construction play — spatial reasoning', 'cognitive', 'advisory',
   52, 65, 130,
   3, 'Block play is one of the most cognitively rich activities available to toddlers. Stacking, balancing, and building with blocks develops spatial reasoning, cause and effect, problem solving, and early mathematical thinking. Research by Casey et al. at Boston University found that block play in early childhood predicts mathematical reasoning at school age better than many formal pre-academic activities. It also builds persistence: blocks fall, plans fail, and the child has to try again.', '* Provide a simple set of wooden unit blocks or large soft blocks from 12 months onward
* Build alongside the child without taking over their plan
* Name what you are doing: "I am making a tall tower. Yours is wider."
* Introduce challenge progressively: can they build as tall as their arm? Can they make a bridge?',
   'Knocking the tower down is part of playing with blocks, not the absence of construction skill. Children demolish towers hundreds of times before they become interested in protecting them.', 'If your 3 year old shows no interest in any construction or stacking activity at all, mention it at the 36 month visit as part of fine motor and play development review.', 'Casey et al. (2008) — Block Play and Math Achievement; Hanline et al. (2010); CDC',
   NULL, FALSE, TRUE),
  ('cognitive-cause-effect', 'Cause and effect — banging objects, dropping things deliberately', 'cognitive', 'advisory',
   21, 26, 34,
   3, 'When a baby bangs a toy on the tray, shakes a rattle, or drops something off a high chair for the 40th time, they are running a physics experiment. They are learning that their action predictably produces an effect, this is the foundational principle behind all problem solving, science, and logical reasoning. It is not misbehavior.', '* Provide toys that respond to actions: rattles, activity gyms, pop up toys
* Let the repetition happen without stopping it prematurely
* Narrate what is happening: "you dropped it and it fell to the floor, again!"',
   'The repetition is the method. Babies repeat cause and effect actions hundreds of times to build the concept into a reliable mental model. Stopping the repetition stops the learning.', 'If your 8 month old shows no interest in producing effects with their actions and is entirely passive with objects, mention it at the 9 month visit.', 'Piaget (1952), Sensorimotor Stage; CDC',
   NULL, FALSE, TRUE),
  ('cognitive-container-play', 'Container play — puts things in and takes them out', 'cognitive', 'advisory',
   39, 43, 56,
   3, 'Babies around 9 to 10 months become fascinated with putting objects into containers and taking them back out. This simple activity teaches spatial reasoning (something can be inside something else), cause and effect, and early classification. It is one of the earliest forms of logical play.', '* Provide simple containers: a box, a bowl, a cup
* Show them how to put a block in and take it out, then step back
* Anything too small for their mouth and large enough to grasp works as a "putting in" object',
   'They will dump the container before filling it to the top. They will put things in and immediately take them out. This back and forth is the whole point.', 'Container play opens naturally when the baby can sit independently and grasp objects. If your 12 month old shows no interest in putting objects into any container, mention it at the 12 month visit.', 'CDC; Piaget (1952)',
   NULL, FALSE, TRUE),
  ('cognitive-counts-to-10', 'Counts to 10', 'cognitive', 'advisory',
   104, 117, 156,
   2, 'Reciting numbers in sequence to 10 by age 3 is an early numeracy milestone. It reflects the ability to memorize and reproduce a sequence, which is a precursor to true counting with one to one correspondence.', '* Count everything in daily life: stairs, snacks, toys being put away
* Songs like "One Two Three Four Five, Once I Caught a Fish Alive" encode the sequence musically
* Counting books reinforce the sequence with visual anchors',
   'Reciting numbers to 10 is easier than understanding what they mean. Most children can count to 10 before they can accurately count 10 objects. Both skills are developing in parallel.', 'If your 3 year old cannot count to 5 at all, it is worth mentioning at the 36 month visit.', 'CDC; Gelman and Gallistel (1978)',
   NULL, FALSE, TRUE),
  ('cognitive-function-of-objects', 'Knows function of objects — spoon for eating, cup for drinking', 'cognitive', 'advisory',
   78, 91, 104,
   3, 'By 18 to 24 months, children understand that common objects have specific functions: spoons are for eating, cups are for drinking, brushes are for hair. This is called functional knowledge and it is the basis of pretend play (using a banana as a phone) and early categorization.', '* Name objects and their function during daily routines: "this is a brush. We use it to brush hair."
* During pretend play, follow their lead, if they hand you the toy phone, answer it
* Simple object function questions ("what do we use to eat?") are appropriate from 18 months onward',
   'Knowing the function of an object does not mean using it correctly every time. A toddler who knows the spoon is for eating but uses it as a drumstick is still demonstrating functional knowledge.', 'If your 2 year old cannot demonstrate the function of common daily objects, mention it at the 24 month visit.', 'CDC; Mandler (1992), How to Build a Baby''s Conceptual System',
   NULL, FALSE, TRUE),
  ('cognitive-identifies-body-parts', 'Identifies own body parts when asked', 'cognitive', 'clinical',
   52, 65, 78,
   2, 'Pointing to their nose, eyes, ears, or belly when asked shows vocabulary comprehension, body self awareness, and the ability to follow simple instructions. It is a standard checkpoint at the 15 and 18 month well child visits.', '* Make it a daily game: "touch your nose!" paired with you touching yours
* Bath time is a natural opportunity: "let''s wash your ears"
* Songs like "Head, Shoulders, Knees and Toes" make this memorable',
   'Toddlers find it funny to point to the wrong body part on purpose. This does not mean they do not know the correct answer.', 'If your 18 month old cannot identify any body part on request, raise it at the 18 month visit.', 'CDC Milestones (2024); AAP',
   NULL, FALSE, TRUE),
  ('cognitive-imitation-play', 'Imitation play — mimics adult actions', 'cognitive', 'advisory',
   34, 39, 52,
   2, 'By 9 months, babies begin to imitate simple actions they observe: clapping, banging two objects together, waving. This is deferred imitation, copying something they have seen before. It is the foundation of pretend play, which builds imagination and social understanding. It also shows the mirror neuron system is functioning.', '* Model simple actions and invite imitation: "I clap, now you clap"
* Play simple imitation games with household objects: stirring a bowl, talking on a toy phone
* React enthusiastically when they copy you',
   'Babies will not copy everything. They will selectively imitate actions that interest them. The observation of imitation in some context is what matters.', 'If your 12 month old shows no imitation of actions at all, mention it at the 12 month visit.', 'Meltzoff (1988); CDC',
   NULL, FALSE, TRUE),
  ('cognitive-matches-shapes-colors', 'Matches shapes and colors', 'cognitive', 'advisory',
   78, 91, 104,
   2, 'Sorting and matching by shape and color is an early classification skill. It shows the child can identify a shared property between objects and use it to group them. This is the foundation of logical and mathematical thinking.', '* Use simple shape sorters and color sorting games
* Describe what you are doing as you sort: "this one is round, it goes with the other round ones"
* Do not force it as a drill. Make it playful.',
   'Getting it wrong is part of learning. A child who enthusiastically puts the wrong shape in the wrong hole is still building the concept.', 'If your 24 month old cannot match even two identical objects or recognize that two things are "the same," mention it at the 24 month visit.', 'CDC; Inhelder and Piaget (1964)',
   NULL, FALSE, TRUE),
  ('cognitive-memory-recalls-events', 'Memory: recalls recent events ("what did we do at the park?")', 'cognitive', 'advisory',
   104, 117, 156,
   2, 'The ability to recall and talk about a past event (not just respond to immediate stimuli) reflects the development of episodic memory and narrative thought. It is also a language milestone, "what did we do today?" is one of the most powerful daily language development prompts.', '* Ask open ended recall questions about recent events: "what did we have for lunch?" "who did you see at the park?"
* Use photos as memory prompts to scaffold recall
* Model recall yourself: "today we went to the store. We bought apples."',
   'Memory at this age is patchy and often out of sequence. They will skip the most important parts and remember something random. This is normal.', 'If your 3 year old cannot recall or discuss any recent event at all, it is worth raising at the 36 month visit.', 'Nelson (1993), Episodic Memory Development; CDC',
   NULL, FALSE, TRUE),
  ('cognitive-mine-yours', 'Understands mine/yours/his/hers', 'cognitive', 'advisory',
   78, 91, 104,
   3, 'Possession concepts (mine, yours) require the child to understand perspective: the same object belongs to different people from different points of view. This is an early theory of mind skill and directly underlies the concept of sharing, which cannot be expected to work until this understanding is in place.', '* Narrate possession consistently in daily interactions: "that is your cup. This is my cup."
* Use possessive pronouns in simple contexts throughout the day
* Picture books with clear ownership scenarios are useful at this age',
   '"Mine" almost always comes before "yours", asserting possession of desired things is developmentally earlier than recognizing another person''s ownership. This is normal.', 'If your 24 month old has no concept of possession at all and treats all objects as equally available to everyone, note it as part of broader language and social development monitoring.', 'Fasig (2000), Toddlers'' Understanding of Mine and Yours; CDC',
   NULL, FALSE, TRUE),
  ('cognitive-more-all-done', 'Understands "more" and "all done" — use with meals', 'cognitive', 'advisory',
   26, 34, 52,
   3, '"More" and "all done" are among the most useful first communication concepts for both parents and babies. Babies understand these concepts before they can speak the words, which means they can be taught as signs or early words from 6 months onward. A baby who can signal "more" or "all done" communicates more effectively and shows less feeding related frustration.', '* Use the words consistently at every meal: "do you want more?" (offer more) "all done?" (show clean hands or remove plate)
* Pair with simple signs if you use baby sign language: open and close hand for "more," wave hands flat for "all done"
* Respond immediately and consistently when the baby signals, this teaches that communication works',
   'Early signs and words will be approximate. A clapping motion used for "more" still counts. The function (communicating the request) matters more than the exact form.', 'If your 12 month old has no way to signal hunger, fullness, or wanting more (verbally or gesturally), discuss communication development at the 12 month visit.', 'Goodwyn et al. (2000), Baby Sign Language Research; CDC; AAP',
   NULL, FALSE, TRUE),
  ('cognitive-music-rhythm', 'Music and rhythm response — move to music', 'cognitive', 'advisory',
   0, 12, 156,
   3, 'Infants are born with sophisticated musical sensitivity. Research by Sandra Trehub shows that babies can detect changes in rhythm, pitch, and melody from the first weeks of life. Music activates overlapping auditory, motor, and emotional brain networks simultaneously, which is why musical engagement in infancy and early childhood is associated with stronger language, memory, and mathematical reasoning.', '* Play varied music (not just children''s music) and watch how your baby responds
* Move with them to music from birth: swaying, bouncing, rocking in rhythm
* From 6 months onward, give them instruments: a drum, shakers, a simple xylophone',
   'You do not need formal music classes for this. Dancing in the kitchen to any music you enjoy is the mechanism.', 'This window is always open. Consistent musical engagement at any age produces measurable benefits. Start now if you haven''t yet.', 'Trehub (2003); Moreno et al. (2011), Music Training and Language; AAP',
   NULL, FALSE, TRUE),
  ('cognitive-object-permanence-emerging', 'Object permanence emerging — notices when toy disappears', 'cognitive', 'advisory',
   17, 26, 39,
   2, 'Object permanence is the understanding that things exist even when you cannot see them. It begins to emerge around 4 to 5 months, a baby will briefly look for a toy that was in their hand and dropped. Fully established object permanence (actively searching for a hidden object) typically develops by 9 months. This is a foundational cognitive milestone described by Piaget.', '* Play early peek a boo: cover your face, then uncover it
* Drop a toy just out of sight and watch to see if the baby looks for it
* Cover a toy partially with a cloth and see if they reach for it',
   'Early versions of this behavior are brief and inconsistent. Sustained interest in finding hidden objects comes a few months later.', 'If your 9 month old shows no interest in finding partially hidden objects, bring it up at the 9 month visit.', 'Piaget (1954), Object Permanence; CDC; Baillargeon (1987)',
   NULL, FALSE, TRUE),
  ('cognitive-object-permanence-solid', 'Object permanence solid — searches for hidden objects', 'cognitive', 'clinical',
   34, 39, 52,
   2, 'By 9 months, most babies will actively search for an object completely hidden under a cloth or behind a barrier. This is the fully formed version of object permanence. It means the child is holding a mental representation of the object in their mind. Absent object permanence by 12 months is a cognitive flag.', '* Hide a toy under a blanket in front of the baby and watch them lift it to find the toy
* Increase the difficulty: hide the toy under one of two cloths and see if they choose correctly
* Peek a boo continues to be valuable practice',
   'The "A not B error" is normal at this age: if you hide a toy in location B after always hiding it in location A, the baby will often look in location A. This is a normal phase of development.', 'If your 12 month old cannot find a toy hidden under a cloth, mention it at the 12 month well child visit.', 'Piaget (1954); Baillargeon (2004); CDC',
   NULL, FALSE, TRUE),
  ('cognitive-outdoor-exploration', 'Outdoor exploration and curiosity', 'cognitive', 'advisory',
   26, 52, 156,
   3, 'Outdoor environments provide a uniquely rich cognitive development context. Nature is unpredictable, variable, and sensory rich in ways that indoor play environments rarely are. Research by Frances Kuo and others links outdoor time to better attention, reduced stress hormones, and improved executive function in children. It also provides unstructured problem solving opportunities.', '* Aim for at least 60 minutes of outdoor time per day (WHO recommendation for ages 1 to 5)
* Let the environment drive the play, resist structuring every outdoor moment
* Mud, sand, sticks, rocks, and puddles are developmentally excellent play materials',
   'Weather protection (sunscreen, layers, rain gear) removes most barriers to outdoor time. "No bad weather, only bad clothing" is a reasonable operating principle.', 'If outdoor time is rare due to urban environment or climate, indoor sensory play (water, sand, playdough, painting) provides a partial substitute.', 'Kuo and Faber Taylor (2004), Outdoor Play and Attention; WHO Physical Activity Guidelines for Under 5s',
   NULL, FALSE, TRUE),
  ('cognitive-points-to-pictures', 'Points to pictures in books when named', 'cognitive', 'advisory',
   47, 52, 65,
   2, 'Pointing to the named picture in a book (where is the cat?) requires recognizing a 2D image as representing a real object and connecting a heard word to its meaning. It is a sign of receptive vocabulary growth and early reading readiness.', '* During reading, pause and ask: "where is the dog?" and point to it yourself first to model
* Use simple books with one large image per page
* Build up from 1 picture per page to full illustrated scenes as skill grows',
   'They may point to the wrong picture and laugh. That is fine. The question is whether they can do it correctly sometimes, not always.', 'If your 15 month old cannot point to any named picture in a familiar book, mention it at the 15 month visit.', 'CDC; AAP Literacy Guidelines',
   NULL, FALSE, TRUE),
  ('cognitive-pretend-play-complex', 'Complex pretend play — multi-step scenarios', 'cognitive', 'advisory',
   78, 104, 130,
   2, 'Complex pretend play (multi step scenarios like cooking dinner for dolls, taking toys on a trip, acting out a doctor visit) shows advanced symbolic thinking, narrative construction, and social understanding. It predicts language ability, creativity, and the capacity for perspective taking. Research by Jerome Singer and Sandra Russ links rich pretend play at 2 to 3 years to better emotional regulation and creativity at school age.', '* Set up simple play scenarios: a play kitchen, a pretend doctor kit, stuffed animals as characters
* Join the play and follow their script, do not take over
* Introduce new elements to extend the scenario: "what does the baby want for dinner?"',
   'Children at this age frequently shift scenarios mid play. The lack of a sustained storyline is normal.', 'If your 3 year old has no pretend play and no symbolic use of objects at all, raise it at the 36 month visit.', 'Singer and Singer (1990); Russ (2004); CDC',
   NULL, FALSE, TRUE),
  ('cognitive-pretend-play-emerging', 'Pretend play emerging — feeds stuffed animal, talks on toy phone', 'cognitive', 'advisory',
   52, 65, 78,
   2, 'Early pretend play (feeding a stuffed animal, pretending to drink from an empty cup, talking into a toy phone) shows the child can hold a mental representation of an action separate from the real action. This is a sign of symbolic thinking, which is foundational for language, reading, and abstract reasoning.', '* Provide simple props: a toy phone, a stuffed animal, a small bowl and spoon
* Model pretend actions: pretend to drink from the empty cup and offer it to the baby
* Follow their lead, if they are feeding the bear, add to the story: "mmm, is the bear hungry?"',
   'Early pretend play looks very simple: one action, one object. Complex scenarios come later. A baby who picks up a banana and holds it to their ear has just pretended, that counts.', 'No pretend play at all by 18 months is a flag worth raising. It is also one of the indicators reviewed in the M CHAT autism screening.', 'Ungerer and Sigman (1981); AAP; CDC',
   NULL, FALSE, TRUE),
  ('cognitive-recognizes-caregiver', 'Recognizes and responds to primary caregiver', 'cognitive', 'clinical',
   4, 8, 17,
   2, 'The ability to distinguish the primary caregiver from strangers is one of the earliest signs of social cognition and memory. It begins with recognition by smell (from the first weeks) and grows to include face and voice recognition by 2 months. It is the neurological foundation for attachment.', '* Spend face to face time without a screen or distraction
* Use your voice consistently as the primary soothing tool
* Let the baby see your face during feeds and diaper changes, not just the ceiling',
   'Recognition of the primary caregiver comes before recognition of secondary caregivers. A baby who lights up for their mother but is neutral about grandma is developing normally.', 'If your 4 month old shows no differential response to familiar versus unfamiliar faces or voices, raise this at the 4 month visit.', 'AAP; DeCasper and Fifer (1980), Neonatal Recognition of Mother''s Voice',
   NULL, FALSE, TRUE),
  ('cognitive-same-different', 'Understands same/different', 'cognitive', 'advisory',
   104, 117, 130,
   2, 'The concept of same and different is a foundational logical operation. It is required for sorting, matching, classifying, and eventually reading (these two letters are the same; these are different). It typically emerges around 24 to 30 months.', '* Play matching games: "find the one that looks the same as this"
* Narrate sameness and difference in daily life: "you have the same shoes as your friend"
* Simple memory card matching games are excellent for this age',
   'They will confuse same and different verbally long after they can demonstrate the concept by sorting. Trust the action over the word.', 'If your 30 month old cannot complete a simple two piece matching task, raise it at the 30 month visit.', 'CDC; Inhelder and Piaget (1964)',
   NULL, FALSE, TRUE),
  ('cognitive-self-recognition-mirror', 'Recognizes self in mirror', 'cognitive', 'clinical',
   12, 17, 34,
   2, 'Self recognition in a mirror (the "rouge test", touching a spot on their own nose when they see it in the mirror) is one of the most studied cognitive milestones. It typically emerges between 15 and 24 months and is considered a marker of self awareness and early theory of mind. Younger babies are social with the mirror, treating it as another baby; older babies recognize themselves.', '* Give babies regular access to a safe, unbreakable mirror
* Comment on what they see: "that is you!"
* Watch for the transition from treating the reflection as a friend to touching their own face after seeing it in the mirror',
   'Enjoying the mirror without self recognition is completely normal through 12 months and beyond. The formal test involves applying a mark to the child''s face and seeing if they touch their own face versus the mirror.', 'Absent self recognition by 24 months alongside other social cognitive delays is worth raising with your pediatrician.', 'Amsterdam (1972); Gallup (1970); CDC',
   NULL, FALSE, TRUE),
  ('cognitive-shape-sorter', 'Simple puzzle / shape sorter', 'cognitive', 'advisory',
   43, 52, 65,
   3, 'Shape sorters and simple puzzles (peg puzzles, single piece inset puzzles) develop spatial reasoning, problem solving, and visual discrimination. The child must recognize the shape, orient the piece, and match it to the correct space. Failure and adjustment is built into the activity, it is one of the earliest structured problem solving contexts.', '* Start with 2 to 4 piece puzzles with large pieces and knob handles
* Shape sorters with 3 to 4 shapes are more manageable than the classic 10 shape version at first
* Resist inserting the piece for them, let them work it out, even if it takes minutes',
   'They will try to force the wrong piece into the wrong space. This is not a sign of low intelligence. It is the normal iteration of trial and error problem solving.', 'If your 15 month old has no interest in shape based activities and cannot fit even a peg into a round hole, mention it at the 15 month visit.', 'CDC; Piaget (1952)',
   NULL, FALSE, TRUE),
  ('cognitive-simple-problem-solving', 'Simple problem solving — how to get toy from shelf', 'cognitive', 'advisory',
   78, 104, 130,
   2, 'By 18 months, children begin to solve simple physical problems: using a stick to reach something, pulling a blanket to retrieve a toy on top of it, stacking boxes to reach a shelf. These are signs of means end thinking, the ability to plan a sequence of actions to reach a goal. It is an early indicator of executive function.', '* Create simple problem solving opportunities: put a toy just out of reach and provide a tool or stepping stool
* Resist the urge to solve it for them, give them time to work it out
* Narrate the process after: "you pulled the blanket, and the toy came with it"',
   'The first attempts will fail. Repeated failure followed by a successful solution is exactly what builds problem solving capacity.', 'If your 2 year old cannot retrieve an object using any indirect method (pulling, using a tool, asking for help), it is worth noting.', 'CDC; Piaget; Willats (1990), Means End Reasoning in Infants',
   NULL, FALSE, TRUE),
  ('cognitive-time-concepts', 'Understands time concepts: morning, afternoon, night', 'cognitive', 'advisory',
   104, 117, 130,
   3, 'Understanding basic time language (morning, afternoon, tonight, yesterday, tomorrow) typically develops between 24 and 30 months. It helps children anticipate daily structure, which reduces anxiety and improves cooperation. "We will go to the park this afternoon" only works as a communication tool if the child has a basic concept of afternoon.', '* Use time language consistently in daily narration: "good morning," "this afternoon we are going to..."
* A visual daily schedule (pictures of the sequence of events) helps make abstract time concepts concrete
* Do not expect accuracy, a child who says "yesterday" for any past event is on track',
   'Past, present, and future tense in language take years to fully develop. "Yesterday" being used for last week, or "tomorrow" for any future event, is normal through age 4.', 'If your 3 year old has no concept of day/night or today/tomorrow, it is worth noting at the 36 month visit.', 'CDC; Harner (1975), How and When Children Learn Temporal Language',
   NULL, FALSE, TRUE),
  ('cognitive-visual-stimulation', 'Visual stimulation — high contrast patterns, faces', 'cognitive', 'advisory',
   0, 0, 8,
   2, 'Newborns can only focus clearly at about 8 to 12 inches and see in limited color. High contrast black and white patterns activate the visual cortex more powerfully than pastel colors at this stage. Faces are the most interesting thing in a newborn''s world and the most important visual input for brain development.', '* Hold your face close (8 to 12 inches) during alert time and make slow, exaggerated expressions
* Use black and white picture cards or books during tummy time
* Pastel nursery decor is fine, but not stimulating, use high contrast items during waking hours',
   'You do not need to buy anything special. Your face is the most powerful visual stimulus available.', 'This window matters most in the first 6 to 8 weeks. After that, color vision improves rapidly and high contrast loses its special advantage.', 'Fantz (1961), Visual Preferences of Newborns; AAP',
   NULL, FALSE, TRUE),
  ('cognitive-visual-tracking', 'Visual tracking — smooth follow across midline', 'cognitive', 'clinical',
   4, 8, 17,
   2, 'Tracking a moving object smoothly with the eyes (rather than in jerky, uncoordinated movements) is an early sign that the visual and motor systems are integrating correctly. Crossing the midline of the body with the eyes, following an object from one side of the face to the other, is a specific developmental milestone checked at the 2 month visit.', '* Slowly move a toy from one side to the other in front of the baby''s face
* Use a bright or high contrast object about 12 inches away
* Do this when the baby is alert and not tired',
   'Eyes that occasionally cross or wander in the first weeks are often normal as the muscles strengthen. It is sustained, alternating crossing that warrants attention.', 'If your baby cannot track a slowly moving object smoothly by 3 months, raise it at the 2 or 4 month visit. Your pediatrician will assess this directly.', 'CDC Milestones; AAP 2 Month Well Child Visit',
   NULL, FALSE, TRUE),
  ('language-1step-commands', 'Follows 1-step commands without gesture', 'language', 'clinical',
   52, 65, 78,
   2, 'Following a one step command without a gesture (like "get your shoe" without pointing at it) shows that language comprehension has moved beyond simple word recognition. The brain is now processing the meaning of an instruction and directing the body to respond. This is a key checkpoint at the 15 and 18 month visits.', '* Give single step instructions using clear, simple words: "sit down," "bring it here," "wave bye"
* Resist pointing or adding gestures, the goal is to test and build word comprehension alone
* Praise and repeat: "yes, that is your shoe, you found it"',
   'Children this age will sometimes comply and sometimes completely ignore you. Inconsistent response is normal. No response at all is what warrants attention.', 'If your 18 month old cannot follow a single command without you pointing or showing them, raise it at the 18 month visit.', 'CDC Milestones (2024); AAP 18 Month Visit Guidelines',
   NULL, FALSE, TRUE),
  ('language-2-word-combinations', 'Two-word combinations ("more milk," "daddy go")', 'language', 'clinical',
   78, 91, 104,
   1, 'Two word combinations, "more milk," "daddy go," "big dog", represent a qualitative leap in language. The child is not just labeling things; they''re constructing meaning. This milestone typically follows the 50 word vocabulary milestone and usually appears between 18 and 24 months. Absent two word combinations by 24 months is a language red flag that nearly always correlates with the absence of the 50 word milestone.', '* Model two word utterances naturally: when your child says "milk," expand to "more milk" or "cold milk"
* Don''t correct, expand. Corrections discourage output. Expansions model without punishing.
* Pair words with actions: "ball throw," "shoes on," "mama sit"',
   'Two word combinations don''t need to be grammatically correct. "More" + any noun counts. "Up" + any name counts. Grammar develops much later.', NULL, 'CDC Developmental Milestones (2024); AAP 24 Month Well Child Visit Guidelines; Nelson (2022), Language Development Research',
   NULL, FALSE, TRUE),
  ('language-2step-commands', 'Follows 2-step commands', 'language', 'clinical',
   91, 104, 117,
   2, 'Following a two step command without prompts ("get your shoes and bring them to me") requires holding two pieces of information in working memory and executing them in sequence. This represents a significant leap in cognitive and language processing from the one step command stage.', '* Start with two steps that are naturally connected: "go get your cup and put it on the table"
* Give the instruction once and wait, do not repeat immediately
* If they forget the second step, gently prompt: "and then what?"',
   'Two step commands are much harder when a child is tired, hungry, or distracted. Test this during calm alert times for accurate results.', 'If your 27 month old cannot follow a two step command, raise it at the 30 month visit.', 'CDC Milestones (2024); AAP',
   NULL, FALSE, TRUE),
  ('language-3-word-sentences', '3-word sentences', 'language', 'clinical',
   104, 117, 130,
   1, 'Three word sentences, "I want milk," "daddy come here," "no more nap", mark the transition from telegraphic speech to early grammar. They typically appear between 24 and 30 months. By 30 months, most children are using 3 word sentences regularly. The presence of consistent 3 word sentences is a primary assessment point at the 30 month well child visit, which the AAP added specifically for developmental surveillance.', '* Continue modeling slightly longer speech than what your child produces, if they use 2 word combos, you use 3 word sentences back to them
* Ask open ended questions: "What happened?" rather than "Did you like it?"
* Avoid finishing their sentences, give them time to complete the thought',
   'Grammar errors at this stage are normal and expected. "I goed" instead of "I went" is a sign of language development, not a mistake to correct.', NULL, 'CDC Developmental Milestones (2024); AAP 30 Month Well Child Visit; Tomasello & Brooks (1999), Grammar Acquisition',
   NULL, FALSE, TRUE),
  ('language-asks-why', 'Asks "why" questions — engage them, don''t dismiss', 'language', 'advisory',
   104, 117, 130,
   3, 'The why question phase (which typically begins around 27 to 30 months and peaks between 3 and 4 years) represents a massive cognitive leap. The child has discovered that the world is explicable, that things have causes, and that you know things they do not. Every "why" is a causal reasoning request. Research by Chouinard (2007) found that children ask up to 100 questions per hour during this phase, and that the quality of the answers they receive significantly predicts scientific reasoning ability.', '* Answer why questions genuinely and simply: "because water is heavier than oil"
* If you do not know the answer: "I do not know, let us find out"
* Use the question as a conversation opener rather than a one shot answer',
   'The questions will continue regardless of how well you answer. This is not a test you can pass or fail. It is a drive toward understanding that runs on its own engine.', 'If your 3 year old never asks why about anything, it is a minor flag worth noting, mostly because it suggests less engagement with the causal structure of the world than expected at this age.', 'Chouinard (2007), Why Do Children Ask So Many Questions?; AAP; NAEYC',
   NULL, FALSE, TRUE),
  ('language-babbling', 'Babbling — consonant sounds (ba, da, ma)', 'language', 'clinical',
   12, 17, 26,
   1, 'Babbling, repeating consonant vowel combinations like "ba ba," "da da," "ma ma", is the bridge between cooing and words. It emerges around 4 months and should be well established by 6 months. Absent or significantly reduced babbling by 6 months is one of the most consistent early language red flags. Research shows that babbling frequency and variety predict vocabulary size at 18 months and beyond.', '* Babble back. If they say "ba ba," say "ba ba" back, then add to it: "ba ba, ball."
* Use simple, slow speech when talking to your baby, research shows infant directed speech (what used to be called "baby talk") accelerates language acquisition
* Minimize background TV and audio, language learning requires conversation, not noise',
   'Babbling sounds like nonsense. It is nonsense, and it''s exactly right for this stage. You''re not teaching words yet. You''re teaching conversation rhythm.', NULL, 'CDC Developmental Milestones (2024); Oller et al., Babbling and Early Language Predictors; AAP Developmental Surveillance',
   NULL, FALSE, TRUE),
  ('language-bilingual-note', 'Bilingual household: total vocabulary counts — per-language count is smaller (normal)', 'language', 'advisory',
   0, 0, 156,
   3, 'Bilingual children build vocabulary across two languages simultaneously. This means their count of words in any single language will appear smaller than a monolingual peer at the same age. This is normal and expected. Milestones should be assessed based on total vocabulary across both languages combined. Bilingualism does not cause language delays, research consistently shows it is cognitively beneficial.', '* When pediatricians ask about vocabulary, add up words from both languages and report the combined total
* Maintain both languages consistently, do not sacrifice one to boost the other
* If a delay is suspected, request a speech evaluation from a bilingual clinician',
   'Mixing languages (code switching) is normal and not a sign of confusion. It is a sign of fluency in both languages.', 'Apply the same milestones but count total words across all languages. If the combined total is below threshold, that is when to seek evaluation.', 'Bialystok (2001), Bilingualism in Development; ASHA Bilingual Language Development',
   NULL, FALSE, TRUE),
  ('language-body-parts-5', 'Names 5 body parts', 'language', 'clinical',
   78, 91, 104,
   2, 'Pointing to or naming body parts on request is a sign of growing vocabulary and object identification. It also shows the child can follow instructions and understands that things have labels. By 24 months, most children can identify at least 5 body parts.', '* Make it a game during bath time: "where is your nose? where is your belly?"
* Read books with pictures of faces and bodies and point to the parts
* Use the correct anatomical words, babies learn what you teach them',
   'They will point to the wrong body part sometimes and laugh. This is part of the game. The milestone is whether they can reliably identify a few specific parts on a good day, not every single time.', 'If your 2 year old cannot identify any body parts on request, this is a language comprehension flag worth raising at the 24 month visit.', 'CDC Milestones (2024); Fenson et al.',
   NULL, FALSE, TRUE),
  ('language-books-in-home', '20+ children''s books in the home', 'language', 'advisory',
   0, 26, 104,
   3, 'The number of books in a home is one of the strongest environmental predictors of child literacy outcomes, independent of income and parental education. Research by Evans et al. found that each additional 100 books in the home corresponded to measurably higher adult literacy. The effect at the child level is significant with as few as 20 books. Books that are visible and accessible (on low shelves, in baskets) are used more than books stored in closets.', '* Aim for at least 20 children''s books accessible at the child''s level
* Library cards are free, borrow books regularly if purchasing is a barrier
* Rotate books seasonally to maintain novelty',
   'Board books that are chewed, loved, and worn out are working exactly as intended.', 'If books are scarce in your home, visit your local library this week. Many libraries also have board book lending and gift programs.', 'Evans et al. (2010), Family Scholarly Culture and Children''s Educational Attainment; AAP Literacy Promotion Guidelines',
   NULL, FALSE, TRUE),
  ('language-complex-instructions', 'Follows complex multi-step instructions', 'language', 'advisory',
   130, 156, 182,
   2, 'Following a 3 to 4 step instruction without prompting is a school readiness skill. It requires working memory, sustained attention, and language comprehension all working together. Children who can follow complex instructions transition more smoothly into structured classroom environments.', '* Practice with daily routines: "go to your room, put your shoes by the door, and come back here"
* Break tasks into verbal steps instead of doing them for the child
* If they lose track, ask "what comes next?" rather than restating the whole instruction',
   'Compliance and comprehension are different. A child who understands the instruction but refuses to do it is developmentally different from a child who genuinely does not understand it.', 'If your 3 year old consistently cannot follow more than a single step instruction, discuss it at the 36 month visit.', 'CDC; AAP',
   NULL, FALSE, TRUE),
  ('language-cooing', 'Cooing — first vowel sounds', 'language', 'clinical',
   4, 6, 12,
   2, 'Cooing is the first sign that a baby is experimenting with their voice intentionally. The soft, drawn out vowel sounds (ohhh, ahhh) are not random, they are a baby''s first attempt at communication. They emerge around 4 to 6 weeks and are a precursor to babbling. Absent cooing by 2 months is a clinical red flag for hearing or developmental concerns.', '* Get close and respond when your baby coos. Coo back, smile, wait for them to go again.
* Talk to your baby in a warm, slightly higher pitched voice, this is called infant directed speech and research confirms babies respond to it more than flat adult tone
* Give them quiet, alert time without background noise or screens',
   'Cooing happens most during alert, calm states. A tired or overstimulated baby will not perform. Test your observations when they are well fed and awake.', 'If there is no cooing or vocalization at all by 2 months, raise it at the 2 month well child visit. It may point to hearing concerns or a developmental delay.', 'CDC Milestones (2024); AAP Developmental Surveillance',
   NULL, FALSE, TRUE),
  ('language-counts-objects-5', 'Counts objects 1–5 (not just reciting numbers)', 'language', 'advisory',
   117, 130, 156,
   2, 'True counting (touching each object once and assigning it a number word in sequence) is different from reciting numbers. One to one correspondence is a foundational math skill, the understanding that each item gets exactly one number. It typically develops between 30 and 36 months.', '* Count small groups of physical objects together: "one cracker, two crackers, three crackers, three crackers total"
* Correct gently when they skip an object or count one twice
* Make it tactile: move each item as you count it',
   'Accurate one to one counting for 5 objects by age 3 is the goal. If they can count to 3 accurately, they are on track.', 'If your 3 year old cannot count even 2 objects with one to one correspondence, mention it at the 36 month visit.', 'Gelman and Gallistel (1978); CDC',
   NULL, FALSE, TRUE),
  ('language-counts-to-3', 'Counts to 3', 'language', 'advisory',
   117, 130, 156,
   2, 'Counting to 3 by age 3 is an early numeracy milestone. It reflects the ability to recall a sequence and pair number words with a concept of quantity. Note: "counting" at this age often means reciting the sequence, not yet understanding that each number corresponds to one object.', '* Count everything: stairs, crackers, fingers, steps to the car
* Use fingers to show the count alongside the word
* Books and songs with counting sequences reinforce this naturally',
   'Reciting "one two three" without yet understanding that "three" means a quantity of three is completely normal at this age. True counting with one to one correspondence comes later.', 'If your 3 year old has no interest in counting or numbers at all, mention it at the 36 month visit.', 'CDC Milestones (2024); Baroody (1987)',
   NULL, FALSE, TRUE),
  ('language-first-words', 'First words beyond mama/dada', 'language', 'clinical',
   47, 52, 65,
   1, 'Beyond "mama" and "dada," most children produce their first true words, consistent labels for people, objects, or actions, between 11 and 14 months. "Ball," "dog," "more," "up", these count. Sign language counts. The milestone is not pronunciation perfection; it''s consistent, intentional use of a sound or sign to represent something specific. Not having any first words by 15 months is a language developmental flag.', '* Label everything, constantly: "That''s a cup. Cup." "Here''s your ball. Ball."
* Read aloud daily, pointing to pictures and naming them builds the word object connection
* Baby sign language (more, all done, milk) gives babies a way to communicate before they can speak, it accelerates spoken language, it does not delay it',
   'Words don''t need to be clear to count. A consistent approximation, "bah" always for ball, "dah" always for dog, counts as a word. Don''t set the bar at adult pronunciation.', NULL, 'CDC Developmental Milestones (2024); AAP Language Developmental Surveillance; Fenson et al., MacArthur CDI Norms',
   NULL, FALSE, TRUE),
  ('language-full-sentences', 'Full sentences (4+ words)', 'language', 'clinical',
   130, 156, 169,
   1, 'By 36 months, most children are speaking in sentences of 4 or more words and can be understood by unfamiliar adults roughly 75% of the time. Full sentences mark the point at which language is a reliable communication tool, not just labels and requests, but narrative, explanation, and emotional expression. Absent 4 word sentences by 36 months is a significant language flag.', '* Have real conversations: ask about their day, their feelings, what they noticed
* Read books with storylines, not just picture books, narrative structure builds sentence structure
* Limit screens: at this age, screen time still primarily displaces conversation',
   'Grammar is still developing through age 5–7. Irregular verbs, pronouns, and plurals take years to master. The milestone is sentence length and communicative intent, not grammatical perfection.', NULL, 'CDC Developmental Milestones (2024); AAP 36 Month Well Child Visit; ASHA (American Speech Language Hearing Association) Developmental Milestones',
   NULL, FALSE, TRUE),
  ('language-imitating-sounds', 'Imitates sounds and facial expressions', 'language', 'clinical',
   17, 21, 30,
   2, 'Imitation is the engine of learning. When a baby copies a sound you make, or sticks out their tongue back at you, they are demonstrating the capacity for social learning. This is one of the building blocks of language, empathy, and communication. Imitation of facial expressions can begin as early as the first weeks, but sound imitation solidifies around 4 to 5 months.', '* Make simple sounds close to their face and wait: "ba," "ma," "ah", see if they attempt to copy
* Exaggerate facial expressions: big open mouth, wide eyes, tongue out
* Give them time to respond. The pause after you make a sound matters.',
   'The imitation will be rough and approximate at first. A baby who opens their mouth wide when you do is imitating, even if the sound is not yet right.', 'If your 7 month old shows no imitation of sounds or expressions, mention it at the next visit.', 'Meltzoff and Moore (1977), Infant Imitation Research; CDC',
   NULL, FALSE, TRUE),
  ('language-joint-attention-pointing', 'Pointing — joint attention (sharing interest)', 'language', 'clinical',
   30, 34, 47,
   1, 'Joint attention, pointing at something to share interest with you, then looking back to see your reaction, is one of the most important developmental milestones in the first year. It emerges around 9 months and is the foundation of language, social cognition, and learning. Babies who point more at 9–12 months have larger vocabularies at 18 months. Absent pointing by 12 months is the single strongest behavioral predictor of autism spectrum disorder.', '* Point at things yourself, constantly: "Look, a dog." Then look at your baby to see if they follow your point
* When your baby points, respond immediately: name what they''re pointing at, share the moment
* Engage with whatever captures their attention, joint attention is about shared interest, not directed instruction',
   'There are two kinds of pointing: imperative (pointing to get something) and declarative (pointing to share). Declarative pointing, "look at that cool thing!", is the milestone that matters most and is the autism screening signal. Imperative pointing develops slightly earlier.', NULL, 'Baron Cohen et al., Pointing as ASD Predictor; Carpenter et al. (1998), Joint Attention Research; CDC Developmental Milestones; AAP M CHAT R/F Screening',
   NULL, FALSE, TRUE),
  ('language-knows-name-age', 'Knows full first name and age', 'language', 'advisory',
   130, 156, 182,
   2, 'Knowing and stating their full first name and age (holding up the correct number of fingers) by age 3 shows autobiographical memory, self concept, and language integration. It is also a practical safety milestone, a child who can state their name is better equipped to communicate with an adult if lost.', '* Practice at home in a fun way: "what is your name?" "how old are you?"
* Celebrate birthday awareness, "you are 2 years old now!"
* Teach first and last name for safety purposes as soon as they can manage it',
   'Last name comes later than first name. Middle name is not part of this milestone.', 'If your 3.5 year old cannot state their first name when asked, it is worth a mention at the next visit.', 'CDC; AAP Bright Futures',
   NULL, FALSE, TRUE),
  ('language-label-emotions', 'Label emotions out loud — "you look frustrated"', 'language', 'advisory',
   52, 65, 104,
   2, 'Children who have words for their emotions are significantly better at regulating them. The research on emotional literacy consistently shows that naming a feeling (even for someone else) activates the prefrontal cortex and reduces the intensity of the amygdala response. In plain terms: naming it tames it. This starts with the parent labeling the child''s emotions, not the child doing it themselves.', '* Narrate emotional states during daily life: "you look frustrated that the block won''t stay," "I can see you are really excited"
* Use simple, clear emotion words: happy, sad, angry, scared, surprised, silly
* Name your own emotions too: "I am feeling tired right now"',
   'You are not teaching them to perform emotions, you are building their emotional vocabulary. Even if they never say the words back to you in toddlerhood, the wiring is happening.', 'This window is always open. If you haven''t started, start today. The practice is valuable at any age.', 'Lieberman (2011), Putting Feelings into Words; Zero to Three; Gottman (1997)',
   NULL, FALSE, TRUE),
  ('language-laughing', 'Laughs out loud', 'language', 'clinical',
   8, 12, 17,
   2, 'Laughing out loud (not just smiling) typically emerges around 3 months. It requires the coordination of breath, voice, and social responsiveness all at once. It is a sign the brain is making deeper social connections and that the baby finds the world interesting. Absent laughter by 4 months is worth noting.', '* Gentle tickling, funny faces, and peek a boo are the most reliable triggers at this age
* Pay attention to what makes your specific baby laugh and repeat it
* Laughter is contagious, laugh back, even at their laughing',
   'Some babies are more serious than others and laugh less frequently. The question is whether they laugh at all, not whether they do it constantly.', 'If your baby is not laughing or producing any positive vocalizations by 4 months, bring this up at the 4 month visit.', 'CDC Milestones (2024); Zero to Three',
   NULL, FALSE, TRUE),
  ('language-mama-dada-specific', 'Uses "mama" and "dada" specifically', 'language', 'clinical',
   39, 47, 56,
   1, 'By 9 months, many babies say "mama" and "dada" as sounds without specific meaning. By 12 months, they should be using them specifically, "mama" when looking at mom, "dada" when looking at dad. This transition from babble to intentional label is the first vocabulary moment. It signals that the brain is now mapping sounds to people and objects. Not using any specific words by 12 months is a language red flag.', '* Use "mama" and "dada" in self referential sentences: "Mama is right here." "Dada is coming."
* Point to each parent when saying the word, connect the sound to the face
* Respond enthusiastically (not over the top) when they use the words correctly, positive reinforcement locks it in',
   '"Mama" said while crying for anyone is not the milestone. Specific use, looking at mom and saying "mama", is what you''re watching for.', NULL, 'CDC Developmental Milestones (2024); AAP Language Development Guidelines',
   NULL, FALSE, TRUE),
  ('language-names-colors', 'Names at least 2 colors', 'language', 'advisory',
   104, 117, 130,
   2, 'Color naming is a cognitive and language milestone that emerges around 24 to 30 months. It requires learning abstract category labels (colors are not things, they are properties of things), which is a more complex linguistic concept than naming objects.', '* Name colors in daily life constantly: "here is your red cup," "look at the blue car"
* Use simple color sorting games with blocks or toys
* Read books that feature color concepts',
   'Color vision is usually fine even if naming is delayed. Many children confuse color names (calling blue "green") long after they can perceive the difference. Naming comes later than perception.', 'If your 3 year old cannot name a single color reliably, it is worth mentioning at the 36 month visit.', 'CDC Milestones (2024); Shatz et al. (1996)',
   NULL, FALSE, TRUE),
  ('language-narrate-meals', 'Narrate meals — "we''re eating broccoli" builds food vocabulary', 'language', 'advisory',
   0, 26, 104,
   3, 'Mealtimes happen 3 times a day, every day, for years. That makes them one of the most powerful and underused language development settings. Narrating the food, describing textures and colors, naming what is on the plate, and asking open ended questions about the meal creates thousands of language learning moments per week.', '* Name every food on the plate: "that is broccoli. It is green and crunchy."
* Describe sensory properties: "this soup is warm. Is it too hot?"
* From 18 months onward, ask open questions: "what do you think this tastes like?"',
   'You do not need to turn every meal into a lesson. Casual narration is more natural and sustainable than formal teaching.', 'If meals are quiet and screen based, this is an easy practice to start this week. One narrated meal per day is better than none.', 'Hart and Risley (1995), Meaningful Differences; AAP Language Promotion',
   NULL, FALSE, TRUE),
  ('language-pronouns', 'Uses pronouns — I, me, you', 'language', 'clinical',
   91, 104, 117,
   2, 'Using pronouns correctly requires understanding that different people have different perspectives, "I" changes based on who is speaking. This is a significant cognitive and linguistic step. Pronoun use typically develops between 21 and 27 months. Persistent use of the child''s own name in place of "I" past 30 months is a flag worth noting.', '* Model pronoun use constantly: "I am eating. You are eating. We are eating."
* Do not correct errors directly, expand and rephrase: if they say "Emma want cookie," say "You want a cookie? Here you go."
* Books with first and second person narration are helpful',
   'Pronoun reversal ("you want milk" when they mean "I want milk") is very common at 2 years and usually resolves on its own.', 'If your 30 month old is not using "I" or "me" at all, raise it at the 30 month visit.', 'CDC Milestones (2024); Chiat (1986)',
   NULL, FALSE, TRUE),
  ('language-read-aloud-daily', 'Read aloud every day — build the habit', 'language', 'advisory',
   0, 0, 52,
   1, 'Reading aloud from birth is one of the highest impact things a parent can do for language development, school readiness, and the parent child relationship. The AAP recommends reading aloud starting at birth. Children who are read to daily have significantly larger vocabularies, better literacy skills, and stronger cognitive development by school age. The habit established in the first year carries through childhood. It requires no special books, no special voice, and no special time, just consistency.', '* Start now, regardless of the baby''s age, they benefit from the voice, rhythm, and closeness from day one
* Any book counts. Board books, picture books, whatever''s available.
* Make it a daily routine: before the first nap, at bedtime, during a feed',
   'Your baby will not understand a word. Read anyway. The sound of language, the rhythm of sentences, and the close physical experience are what matter in the first months. Comprehension comes later.', 'It''s never too late to start reading aloud. If the habit isn''t established, start with one short book before bed tonight and build from there.', 'AAP Policy on Literacy Promotion (2014); REACH OUT AND READ Research Base; Strickland & Morrow, Emergent Literacy; Bus et al. (1995), Meta analysis on shared reading',
   NULL, FALSE, TRUE),
  ('language-read-with-pointing', 'Read aloud with pointing — connecting words to pictures', 'language', 'advisory',
   26, 52, 104,
   2, 'Once a baby can sit and focus on a book (around 6 months), pointing to pictures while you name them accelerates vocabulary acquisition significantly. The connection between the spoken word and the image on the page is how children learn that objects have labels. Research shows that children read to with pointing have larger vocabularies by age 2 than those simply read to in a flat narrative style.', '* Point to the picture as you say the word: "look, a dog. The dog is running."
* Pause and let the child point back when they are old enough (8 to 10 months onward)
* Board books with large, clear pictures are ideal for this',
   'You do not need to follow the story text word for word. Describing what you see in the pictures is just as effective.', 'If you have been reading without pointing, start today. It is never too late to add this layer.', 'Bus et al. (1995); Whitehurst and Lonigan (1998); AAP Literacy Promotion',
   NULL, FALSE, TRUE),
  ('language-responds-to-name', 'Responds to own name', 'language', 'clinical',
   17, 21, 30,
   1, 'Reliably turning toward the sound of their own name, as opposed to any voice or sound, typically develops between 5 and 7 months. It''s a sign that the brain is processing social information specifically: their name is meaningful in a way that random sounds are not. Not responding consistently to their name by 7 months is a red flag for hearing issues and is also one of the core early screening indicators for autism spectrum disorder.', '* Use their name frequently and consistently, not just nicknames
* Test when they''re not looking at you: call their name from across the room and see if they turn
* Make name calling a positive event, say the name, they turn, you smile and engage',
   'Babies this age are easily distracted. Test name response when they''re alert and not engrossed in something. One or two failed attempts don''t indicate a problem.', NULL, 'CDC Developmental Milestones (2024); Nadig et al. (2007), Name Response as Early ASD Predictor; AAP Autism Screening',
   NULL, FALSE, TRUE),
  ('language-screen-time-displacement', 'Screen time displaces language — minimize background TV', 'language', 'advisory',
   0, 0, 156,
   2, 'Background TV reduces parent to child verbal interaction. Studies show that for every hour of TV playing in the background, parents speak approximately 770 fewer words to their child. Children in homes with frequent background TV have smaller vocabularies and shorter conversational exchanges. Screen time is not the only language variable, but it is one of the most controllable.', '* Turn off the TV when it is not being actively watched
* Designate specific screen times and keep the rest of the day screen free
* If screens are on, co watch and narrate: "what is that character doing?"',
   'Occasional TV exposure is not harmful. The concern is habitual background noise that competes with conversation.', 'This applies throughout childhood. If screens are a constant background feature of your home, reducing them is one of the highest impact language interventions available.', 'Christakis et al. (2009), TV and Language; AAP Screen Time Policy (2016, updated 2024)',
   'getfamilyforce.com/playbook-screen-time', FALSE, TRUE),
  ('language-serve-return', 'Serve and return — the foundation of language', 'language', 'advisory',
   0, 0, 17,
   1, 'Harvard''s Center on the Developing Child calls serve and return "the most important thing parents can do for brain development." The concept: your baby makes a sound, a gesture, or a facial expression (the "serve"). You respond, make eye contact, mimic, talk back, engage (the "return"). Every exchange like this builds neural connections. Millions of these exchanges in the first years of life wire the architecture for language, emotional regulation, and learning. It''s not the content that matters, it''s the back and forth.', '* Narrate everything you do: "I''m changing your diaper now. Left leg first."
* When your baby coos, coo back. When they look at something, look at it too and name it.
* Put the phone down during feeding and face to face time, your face is the most interesting thing in their world right now',
   'You don''t need special activities or toys. You are the activity. Talking to your baby while doing ordinary things, getting dressed, making breakfast, driving, is exactly what this looks like in practice.', 'This window never truly closes, serve and return matters throughout childhood. If you''re starting late, start now. The density of these interactions early in life matters most, but every additional exchange still builds something.', 'Harvard Center on the Developing Child, Serve and Return; National Scientific Council on the Developing Child; AAP Literacy Guidelines',
   NULL, FALSE, TRUE),
  ('language-singing-together', 'Singing together — music accelerates language', 'language', 'advisory',
   26, 52, 104,
   3, 'Music and language share overlapping neural networks. Children who are sung to regularly show measurably better phonological awareness, vocabulary, and memory for sequences. Songs encode words in melody, which makes them easier to recall. Research by Sandra Trehub shows that infants have sophisticated musical sensitivity from birth.', '* Sing during routines: bath time, car rides, getting dressed
* Repeat the same songs many times, repetition is the mechanism
* Interactive songs that involve the child''s name or body parts add an extra layer of engagement',
   'You do not need to be a good singer. Your child is not a music critic. They respond to your voice and the rhythm, not your pitch accuracy.', 'If singing is not part of your routine yet, starting at any age has demonstrable benefits. Pick three songs and repeat them this week.', 'Trehub (2003), Musical Predispositions in Infancy; Bryant et al. (1990); AAP',
   NULL, FALSE, TRUE),
  ('language-social-smile', 'Social smile appears — first intentional interaction', 'language', 'clinical',
   4, 6, 12,
   1, 'The social smile, a smile in direct response to your face and voice, not gas, typically appears around 6 weeks. It''s the first sign that your baby is engaging with the social world intentionally. Absent social smiling by 3 months is a clinical red flag and one of the early screening indicators for autism spectrum disorder. The smile is also the beginning of the serve and return emotional exchange that drives language and attachment development.', '* Get close, babies can only focus clearly at 8–12 inches
* Smile, talk, and wait. Give them time to respond. The social smile takes a beat.
* Respond to every smile: smile back, say something, make it a two way exchange',
   'Smiling at the ceiling or a pattern on the wall is reflexive, not social. The social smile is specifically triggered by a face. Don''t count random smiles as the milestone.', NULL, 'CDC Developmental Milestones (2024); AAP Autism Screening Guidelines; Johnson et al. (2015), Early Social Smile and ASD Detection',
   NULL, FALSE, TRUE),
  ('language-songs-rhymes', 'Introduce nursery rhymes and songs', 'language', 'advisory',
   0, 12, 52,
   2, 'Songs and rhymes are one of the oldest and most effective language tools. The repetition builds vocabulary through pattern recognition. The rhythm and rhyme make words easier to remember. Research shows that phonological awareness (the ability to hear and manipulate sounds) is a strong predictor of reading ability, and nursery rhymes are an early builder of this skill.', '* Pick 3 to 5 simple songs and sing them consistently: "Twinkle Twinkle," "Itsy Bitsy Spider," "Row Your Boat"
* Use hand gestures or actions alongside the song
* Repetition is the whole point. Sing the same songs many times.',
   'You do not need to be a good singer. Babies do not care about pitch or quality. They care about your face, your voice, and the pattern.', 'If you haven''t started, start today with one song. Repeat it every day this week.', 'Bryant et al. (1990), Nursery Rhymes and Reading; AAP',
   NULL, FALSE, TRUE),
  ('language-speech-clarity-family', 'Family can understand 75%+ of speech', 'language', 'clinical',
   78, 91, 104,
   2, 'By 24 months, the people who know the child best (parents, siblings, close caregivers) should be able to understand the majority of what they say. If even familiar adults are struggling to interpret their speech at 2 years, a speech evaluation is appropriate.', '* Pay attention honestly to how much you understand versus how much you guess from context
* Ask your partner or other family members how much they understand
* At the 24 month visit, report your honest assessment to the pediatrician',
   'Strangers will always understand less than family. The 75% family comprehension target at 24 months is different from the stranger comprehension target, which is lower.', 'If your family cannot understand the majority of your 2 year old''s speech, ask for a speech language referral at the 24 month visit.', 'ASHA; CDC Milestones (2024)',
   NULL, FALSE, TRUE),
  ('language-startle-to-sound', 'Responds to sounds / startles', 'language', 'clinical',
   0, 1, 8,
   1, 'From birth, a baby should startle to sudden loud sounds and calm to a familiar voice. These are the earliest signs that hearing is functional and that the auditory system is working. Absent or inconsistent response to sound in the first weeks can be an early indicator of hearing loss, which affects 1–3 per 1,000 newborns. Early detection and intervention produces dramatically better language outcomes.', '* Newborn hearing screen is done in the hospital before discharge, confirm it was completed and ask for the result
* At home: clap or make a sudden sound near (not directly at) the baby''s ear and watch for a startle response
* Note whether your baby calms to your voice specifically',
   'Newborns sleep deeply and may not startle to sounds when in deep sleep. Test when awake and alert for reliable results.', NULL, 'JCIH (Joint Committee on Infant Hearing) Year 2019 Position Statement; AAP Universal Newborn Hearing Screening',
   NULL, FALSE, TRUE),
  ('language-stranger-understands-50pct', '50% of speech understandable to strangers', 'language', 'clinical',
   91, 104, 117,
   2, 'By 24 months, strangers (people who do not know the child) should be able to understand about half of what the child says. Parents and caregivers can often understand more because they know the child''s speech patterns and context. The stranger comprehension test is a more objective measure of speech clarity.', '* Pay attention to how other adults respond when your child speaks, do they ask for translation often?
* Avoid habitually translating for your child, give them space to communicate directly
* If speech clarity is a concern, mention it to your pediatrician',
   'Some sounds (r, l, th, s blends) are not expected to be mastered until age 5 to 7. Clarity about the words as a whole matters more than individual sound perfection at this stage.', 'If strangers cannot understand any of your child''s speech by 24 months, a speech language evaluation is warranted.', 'ASHA Milestones; CDC',
   NULL, FALSE, TRUE),
  ('language-stranger-understands-75pct', '75% of speech understandable to strangers', 'language', 'clinical',
   104, 117, 130,
   2, 'By 36 months, the goal is that strangers understand approximately 75% of what a child says. This is the benchmark used by speech language pathologists for evaluating speech clarity at age 3. Below this threshold often indicates a speech sound disorder that benefits from early therapy.', '* Note how often you have to translate for your child in interactions with other adults
* Ask your pediatrician at the 36 month visit to assess speech intelligibility
* If unclear, request a speech language pathology evaluation',
   'Background noise, tiredness, and shyness all reduce speech clarity. Assess your child in comfortable, familiar settings for the most accurate picture.', 'If strangers cannot understand the majority of your child''s speech by age 3, request a speech evaluation referral at the 36 month visit.', 'ASHA; CDC Milestones (2024)',
   NULL, FALSE, TRUE),
  ('language-tells-stories', 'Tells a simple story / describes a recent event', 'language', 'advisory',
   156, 169, 195,
   2, 'Telling a story (even a simple one like "we went to the park, I saw a dog, the dog was big") requires narrative structure, memory retrieval, and connected sentence production. It is one of the most advanced language milestones in the early childhood window and a predictor of reading comprehension and academic success.', '* After outings, ask open ended questions: "what happened at the park?" rather than "did you have fun?"
* Build narrative with them: "you told me about the dog, what did the dog do?"
* Use photos from recent events as prompts for storytelling practice',
   'Stories at this age will be out of sequence, missing details, and full of repetition. That is exactly right for this stage.', 'If your 4 year old cannot describe any recent event in connected sentences, a speech and language check is worth requesting.', 'CDC; Applebee (1978), Narrative Development Research',
   NULL, FALSE, TRUE),
  ('language-understands-no', 'Understands "no"', 'language', 'clinical',
   30, 39, 52,
   2, 'Understanding "no", pausing or changing behavior in response to the word, shows that language comprehension is developing. At 9 to 12 months, receptive language (what they understand) is ahead of expressive language (what they say). A baby who understands "no" has reached a key comprehension checkpoint.', '* Use "no" consistently and calmly when redirecting
* Pair it with a physical cue: a gentle hand hold or a redirection to a safe alternative
* Do not overuse "no", it loses meaning if it accompanies everything',
   'Understanding "no" and consistently obeying it are different things. Comprehension comes first. Compliance takes much longer and involves the prefrontal cortex, which is years away from being reliable.', 'If your 12 month old shows no response to "no" or their name, raise hearing and comprehension concerns at the 12 month visit.', 'CDC Milestones (2024); AAP Language Surveillance',
   NULL, FALSE, TRUE),
  ('language-vocab-10-words', 'Vocabulary: 10 words', 'language', 'clinical',
   56, 65, 78,
   1, 'A vocabulary of 10 words by 15–18 months is the standard developmental checkpoint. This is not 10 perfect words, it''s 10 consistent, intentional labels for people, objects, or actions, in any form including sign language. Research on vocabulary development shows a clear acceleration (the "vocabulary spurt") that typically begins after the 10 word milestone. Getting to 10 words is what triggers it.', '* Count consistently: keep a rough mental list of what counts as a word (consistent use, specific meaning)
* Read aloud with pointing: "Where''s the dog? There''s the dog."
* Simple songs with repetition are some of the most effective vocabulary tools at this age',
   'Boys tend to develop vocabulary slightly later than girls. This is well documented and not a reason to ignore red flags, but it provides some normal range context.', NULL, 'CDC Developmental Milestones (2024); Fenson et al., MacArthur CDI Research; AAP 18 Month Well Child Visit Guidelines',
   NULL, FALSE, TRUE),
  ('language-vocab-200-words', 'Vocabulary: 200+ words', 'language', 'clinical',
   91, 104, 117,
   1, 'By 24 months, most children have approximately 200 words, though the range is wide. What matters more than the exact count is that language is growing rapidly and that two word combinations are present. The 200 word milestone signals that the vocabulary spurt is complete and that the child is on track for three word sentences by 30 months. A vocabulary below 50 words at 24 months is the flag, 200 words is the target.', '* Continue daily reading, narrating daily activities, and expanding their utterances
* Name emotions as well as objects: "you look frustrated," "that made you happy"
* Introduce new vocabulary in context: at the park, at the grocery store, in the bath',
   'Children who attend daycare and hear multiple caregivers often have larger passive vocabularies but express fewer words. The gap between what they understand and what they say narrows quickly in this window.', NULL, 'CDC Developmental Milestones (2024); Fenson et al., MacArthur CDI; AAP Language Guidelines',
   NULL, FALSE, TRUE),
  ('language-vocab-50-words', 'Vocabulary: 50 words — the 50-word gate', 'language', 'clinical',
   78, 91, 104,
   1, 'Fifty words is the gate that opens the next stage of language. Research consistently shows that once a child has approximately 50 words, two things happen: vocabulary grows exponentially (some children add 9–10 words per day), and two word combinations begin. The 50 word milestone typically appears between 18 and 24 months. Not reaching it by 24 months is a language flag that nearly always warrants speech evaluation.', '* Keep reading aloud, this is the single highest leverage language intervention
* Expand what they say: if they say "dog," you say "big dog" or "brown dog running." This is called "expansion," and research shows it accelerates vocabulary faster than drilling new words
* Reduce TV/screen time, it displaces conversation, which is the only thing that builds vocabulary at this age',
   'The 50 word count is approximate. The research cares about the range of 40–60. If your child is at 35 words at 22 months, they''re tracking fine. The flag is significantly below 50 at 24 months.', NULL, 'Fenson et al., MacArthur CDI Research; Ganger & Brent (2004), Vocabulary Spurt; CDC Developmental Milestones; AAP Language Guidelines',
   NULL, FALSE, TRUE),
  ('language-waving', 'Waving bye-bye', 'language', 'clinical',
   34, 39, 52,
   2, 'Waving is a social gesture, a deliberate communication with another person. It requires understanding that gestures carry meaning and that you can use your body to communicate without sound. It is also an early indicator of gestural communication, which is part of the same developmental pathway as pointing and language.', '* Wave goodbye every time you leave a room or end a face to face interaction
* Clap and cheer when they wave back, make it rewarding
* Wave during video calls with family to give them more practice opportunities',
   'Some babies wave with their whole arm, some with just their hand, some with fingers splayed. Any intentional goodbye gesture counts.', 'No waving or gestural communication by 12 months is a flag worth raising at the 12 month visit.', 'CDC Milestones (2024); AAP',
   NULL, FALSE, TRUE),
  ('motor-catching-ball', 'Catches a large ball', 'motor', 'advisory',
   104, 130, 156,
   3, 'Catching a large ball (arms extended, trapping the ball against the body) typically develops around 30 to 36 months. It requires anticipating the ball''s trajectory, timing the arm movement, and adjusting for errors in real time. These are visual motor integration skills that also underpin reading and writing.', '* Use a large, soft ball (beach ball size), smaller balls require more precision than toddlers have
* Throw gently and directly to their outstretched arms
* Celebrate any contact with the ball, not just a clean catch',
   'Most toddlers catch by trapping the ball against their chest with both arms, not with a clean hand catch. This is completely correct technique for this age.', 'If your 3 year old cannot interact with a ball at all (catch, kick, or throw), mention it at the 36 month visit.', 'CDC; AAP',
   NULL, FALSE, TRUE),
  ('motor-crawling', 'Crawling (or alternative locomotion)', 'motor', 'clinical',
   26, 34, 43,
   2, 'Crawling is the first time a child can choose where they go. It builds the cross body coordination (left arm with right leg) that is important for later brain development and balance. However, the style of crawling matters less than the intent to move.', '* Provide lots of uninterrupted floor time
* Place favorite toys just out of reach
* Babyproof your home now if you haven''t finished (see Safety section)',
   'Army crawling (on the belly), scooting on the butt, or rolling to get across the room all count as mobility. Some babies skip a traditional hands and knees crawl entirely.', 'If your 10 month old is making no effort to move across the room in any way, talk to your pediatrician.', 'AAP; CDC',
   NULL, FALSE, TRUE),
  ('motor-cruising', 'Cruises along furniture', 'motor', 'clinical',
   34, 43, 52,
   2, 'Cruising (walking while holding onto furniture) is the final bridge to independent walking. It develops the side to side balance and hip strength needed for the first steps.', '* Arrange furniture to create a safe path for laps
* Go barefoot as much as possible: toes provide essential grip and feedback for balance
* Avoid baby walkers with wheels, which can actually delay proper walking development and are a safety risk',
   'Cruising can last for months. Some babies cruise for a long time because they are cautious, even if they have the strength to walk.', 'If your one year old is not cruising or standing while holding on, discuss this at the 12 month visit.', 'AAP; CDC',
   NULL, FALSE, TRUE),
  ('motor-drawing-circle', 'Copies a circle', 'motor', 'advisory',
   104, 117, 130,
   3, 'Copying a circle (drawing a closed, approximately circular shape) is a standard motor milestone around 30 months. It requires more wrist rotation and planning than a straight line. It is a letter readiness skill and a common item on developmental screening tests at age 3.', '* Draw a circle slowly in front of the child and invite them to copy it
* Accept any closed or approximately circular shape
* Practice with finger painting, tracing circles, and drawing on fogged glass',
   'Their circle will look like an oval, or a lumpy potato shape, or a loop. It counts. Geometric accuracy comes years later.', 'If your 3 year old cannot produce any closed round shape at all, raise it at the 36 month visit.', 'CDC Milestones; HELP Strands; AAP',
   NULL, FALSE, TRUE),
  ('motor-drawing-line', 'Copies a vertical line', 'motor', 'advisory',
   86, 104, 117,
   3, 'Copying a vertical line (as opposed to just scribbling) requires the child to observe a shape, form a motor plan, and replicate it. This is called imitation of a stroke and is a precursor to letter formation. It typically develops between 21 and 27 months.', '* Draw a simple vertical line and say "can you make one like this?"
* Do not hold their hand or guide the crayon, copying requires independent execution
* Horizontal lines come after vertical lines; circles come after both',
   'The copy will be rough and approximate. An imperfect vertical line is still a copied vertical line.', 'If your 27 month old cannot copy a simple vertical line, it is worth noting at the 30 month visit.', 'CDC Milestones; HELP Strands; AAP',
   NULL, FALSE, TRUE),
  ('motor-first-steps', 'First steps', 'motor', 'clinical',
   43, 52, 65,
   1, 'First steps typically appear between 10 and 15 months (updated CDC 2022 guidance moved the expected milestone from 12 to 15 months). Most babies take their first independent steps around 12 months. Walking is a clinical milestone, not walking independently by 15 months warrants a pediatrician conversation. It''s one of the key observations at the 12 and 15 month well child visits.', '* Create safe floor space: remove rugs that slip, soft landing surfaces are fine
* Encourage cruising (furniture walking), it builds the balance and strength needed
* Don''t rush it with walkers or push toys that provide too much support too early
* Let them fall. Falling is how balance is learned.',
   'Wide stance, toes turned out, and frequent falls are all completely normal in new walkers. The gait looks strange for months. This is expected.', NULL, 'CDC Developmental Milestones (2022 update); AAP Developmental Surveillance Guidelines; WHO Motor Milestone Windows',
   NULL, FALSE, TRUE),
  ('motor-head-control', 'Head control — holds steady when upright', 'motor', 'clinical',
   4, 12, 17,
   1, 'Steady head control by 4 months is one of the foundational gross motor milestones. It signals that the neck muscles and upper spine are developing correctly. It''s also a prerequisite for solid food readiness, babies who can''t hold their heads up aren''t ready for solids. Absent or significantly delayed head control is one of the first motor red flags pediatricians check for.', '* Tummy time (see above) is the main driver, the work happens there
* Hold baby in supported upright positions during waking hours: facing outward in your arms, in a baby carrier
* At 4 month well child visit, your pediatrician will assess this directly',
   '"Steady" doesn''t mean perfect. Some wobble at 3 months is completely normal. The test is: when held upright and supported at the torso, does the head stay up for several seconds without collapsing?', NULL, 'CDC Developmental Milestones (2024); Denver II Developmental Screening Test; WHO Multicentre Growth Reference Study',
   NULL, FALSE, TRUE),
  ('motor-hopping-one-foot', 'Hops on one foot', 'motor', 'advisory',
   130, 156, 182,
   3, 'Hopping on one foot (taking multiple consecutive hops on the same foot) is a milestone around age 3 to 3.5. It requires single leg balance, dynamic stability, and rhythmic motor planning. It is a precursor to skipping and is commonly assessed at the 4 year visit.', '* Demonstrate hopping and make it a game: "hop like a bunny!"
* Hopscotch (even a rough version) is excellent practice
* Do not push the milestone, it develops on its own timeline',
   'Most children at age 3 can manage 1 to 2 hops before losing balance. Three or more consecutive hops typically consolidates by age 3.5 to 4.', 'If your 4 year old cannot hop on one foot at all, mention it at the 48 month visit.', 'CDC Milestones; AAP 4 Year Visit Guidelines',
   NULL, FALSE, TRUE),
  ('motor-jumping-both-feet', 'Jumping in place — both feet leave ground', 'motor', 'clinical',
   86, 104, 117,
   2, 'Jumping requires significant leg power and the ability to coordinate both sides of the body simultaneously. It is a major milestone for athleticism and physical confidence.', '* Practice jumping off a very small height (like a 2 inch curb) onto a soft surface
* Model the behavior: Look, I jump!
* Use a trampoline with a handle or a soft mat for practice',
   'Many children one foot jump for a long time before they can get both feet off the ground at once. This is a normal progression.', 'If your 2.5 year old cannot jump in place with both feet, it is worth a mention at the 30 month visit.', 'CDC; Help Me Grow',
   NULL, FALSE, TRUE),
  ('motor-jumping-forward', 'Jumps forward', 'motor', 'advisory',
   104, 117, 130,
   3, 'Jumping forward with both feet leaving the ground is a gross motor milestone around age 2.5. It requires explosive leg strength, balance, and coordination of a two foot takeoff and landing. It is a standard item on the 30 month developmental screen.', '* Demonstrate jumping and invite them to try
* Jumping on a soft surface (a mattress, cushions) is easier than jumping on the floor and builds confidence
* Count how far they jumped: "wow, two whole feet!"',
   'Some children jump with one foot slightly ahead of the other at first. True simultaneous two foot jumping develops with practice.', 'If your 30 month old cannot leave the ground with both feet at once in any context, mention it at the 30 month visit.', 'CDC Milestones; AAP',
   NULL, FALSE, TRUE),
  ('motor-kicking-ball', 'Kicking a ball', 'motor', 'advisory',
   65, 65, 86,
   3, 'Kicking a stationary ball emerges around 15 to 18 months. It requires the ability to stand on one leg briefly while the other leg swings forward, a balance skill that represents significant bilateral gross motor coordination. It also requires planning and directionality.', '* Place a large, soft ball in front of the child and demonstrate kicking it
* Start with a ball that does not roll far so they can retrieve it easily
* Celebrate any attempt, even if the "kick" is more of a step on or push',
   'Kicking accurately takes much longer than kicking at all. A kick that goes sideways or barely moves the ball is a successful kick.', 'If your 20 month old cannot kick a stationary ball at all, mention it at the next visit as part of gross motor review.', 'CDC Milestones; AAP',
   NULL, FALSE, TRUE),
  ('motor-object-transfer', 'Transfers objects hand to hand', 'motor', 'clinical',
   21, 26, 34,
   3, 'Transferring an object from one hand to the other (typically emerging around 5 to 6 months) is a significant bilateral coordination milestone. It requires the two sides of the brain to communicate via the corpus callosum. It is also a precursor to more complex bimanual skills like clapping, feeding, and eventually drawing.', '* Offer toys to one hand and observe whether the baby moves them to the other
* Rattles, rings, and soft blocks work well for this, they are easy to hold and transfer
* Do not place objects into the non dominant hand directly; let the transfer happen spontaneously',
   'Some babies hold a toy in one hand for a while before transferring. The transfer does not need to be instant.', 'If your 8 month old never transfers objects and always uses one hand to reach, mention it at the 9 month visit.', 'CDC Milestones; AAP',
   NULL, FALSE, TRUE),
  ('motor-pincer-grasp', 'Pincer grasp develops', 'motor', 'clinical',
   34, 39, 52,
   2, 'The pincer grasp (using the thumb and index finger to pick up small objects) is a major fine motor milestone. It is required for self feeding small bits of food and is the foundation for later skills like drawing and buttoning clothes.', '* Offer small, safe finger foods like O shaped cereal or cooked peas
* Provide toys with small knobs or buttons
* Practice point and touch games with your fingers',
   'It starts messy. They will try to use their whole hand at first. The precision takes time to develop.', 'If your 12 month old cannot pick up a small piece of food with their fingers, mention it to your pediatrician.', 'Denver II; CDC',
   NULL, FALSE, TRUE),
  ('motor-pull-to-stand', 'Pulls to standing', 'motor', 'clinical',
   30, 39, 52,
   2, 'This is the beginning of the transition from floor play to upright life. It requires significant leg and grip strength. Once a baby can pull up, your safety concerns change: they can now reach things on low tables and counters.', '* Ensure heavy furniture is anchored to the wall (tip over risk)
* Provide sturdy surfaces like a heavy coffee table or a sofa for practice
* Lower the crib mattress to the lowest setting immediately',
   'They will often get stuck standing and cry because they don''t know how to sit back down. You will have to help them lower themselves for a week or two until they learn to drop to their diaper.', 'If your child is not attempting to pull up by their first birthday, it warrants a clinical check.', 'CDC; Help Me Grow',
   NULL, FALSE, TRUE),
  ('motor-reaching-grabbing', 'Reaching for and grasping objects', 'motor', 'clinical',
   8, 14, 26,
   2, 'This is the transition from reflexive movements to intentional ones. It requires the eyes and hands to work together (hand eye coordination). It is the foundation for self feeding and playing with toys.', '* Hang toys within reach during floor play
* Offer objects of different sizes and textures
* Encourage baby to reach across the midline of their body',
   'Early attempts will be clumsy. They will miss the object or hit themselves in the face. This is how the brain maps distance and movement.', 'If your 6 month old is not reaching for toys at all, this is a clinical flag that needs a pediatrician assessment.', 'CDC; Help Me Grow',
   NULL, FALSE, TRUE),
  ('motor-roll-back-to-tummy', 'Rolls back to tummy', 'motor', 'clinical',
   12, 17, 26,
   2, 'Rolling from the back to the stomach requires more coordination and muscle control than the reverse. Once a baby can do this, they can often get themselves into a tummy time position independently, which accelerates their motor progress.', '* Stop using sleep positioners or restrictive swaddles immediately if you haven''t already
* Encourage play on the side, which is the halfway point for rolling
* Use a play mat with interesting textures to encourage movement',
   'Once they can roll to their tummy, they might do it in their sleep and then cry because they can''t get back. This is a frustrating but short phase that usually lasts only a week or two.', 'If your baby is not rolling in either direction by 6 months, discuss this with your pediatrician.', 'CDC; AAP',
   NULL, FALSE, TRUE),
  ('motor-roll-tummy-to-back', 'Rolls tummy to back', 'motor', 'clinical',
   8, 14, 21,
   2, 'Rolling from the stomach to the back usually happens first, often accidentally as the baby pushes up during tummy time. It is a sign of increasing core and neck strength. It also marks the beginning of independent mobility.', '* Provide plenty of floor time to practice
* Place toys just out of reach to encourage twisting and reaching
* Cheer when it happens: positive reinforcement encourages them to try again',
   'Some babies do this once and then forget how to do it for two weeks. This is normal. Development is not always a straight line.', 'If your baby is not rolling from tummy to back by 5 months, mention it at your next pediatrician visit. It is usually a sign they need more tummy time practice.', 'CDC Milestones; WHO',
   NULL, FALSE, TRUE),
  ('motor-running', 'Running (first attempts)', 'motor', 'clinical',
   65, 78, 86,
   2, 'Running typically emerges about 6 months after walking. It requires higher level balance and the ability to handle momentum. It is a sign that the gross motor system is maturing.', '* Provide safe, wide open spaces like a park or a carpeted room
* Play games like chase or tag
* Expect lots of falls: choose soft surfaces for practice where possible',
   'The first run looks more like a fast, stiff legged walk. The smooth, rhythmic running motion won''t appear for another year.', 'If your 20 month old is walking well but shows no attempt to move faster or run, mention it at your next visit.', 'CDC Milestones; WHO',
   NULL, FALSE, TRUE),
  ('motor-scribbling', 'Scribbling with crayon', 'motor', 'advisory',
   65, 78, 91,
   3, 'Scribbling is the earliest form of drawing and the precursor to writing. It begins around 15 months with large, whole arm movements and gradually becomes more controlled as the wrist and finger movements develop. The goal at this stage is not recognizable shapes, it is purposeful mark making.', '* Provide large crayons (chunky toddler crayons) and large paper
* Draw alongside them and name what you are doing: "I am making circles"
* Avoid correcting or directing, free mark making at this stage is the goal',
   'Scribbling looks like scribbling. That is what it is supposed to look like. Representational drawing does not typically emerge until age 3 or 4.', 'If your 20 month old shows no interest in making marks on paper with any tool, mention it at the next visit as part of fine motor review.', 'CDC; Kellogg (1969), Stages of Children''s Drawing',
   NULL, FALSE, TRUE),
  ('motor-sitting-supported', 'Sits with support', 'motor', 'clinical',
   12, 17, 26,
   2, 'Sitting with support (using hands for balance or propped in a corner) is the precursor to independent sitting and solid food eating. It shows the trunk muscles are becoming strong enough to hold the weight of the head and upper body.', '* Practice sitting on your lap or on the floor between your legs
* Use pillows for safety but let the baby do the work of balancing
* Keep sessions short to avoid over tiring the back muscles',
   'The tripod sit, where baby leans forward on their hands, is a perfectly normal part of this stage. It counts as supported sitting.', 'If your baby cannot sit even with significant support by 6 months, bring it up at your next visit.', 'Denver II; CDC',
   NULL, FALSE, TRUE),
  ('motor-sitting-unsupported', 'Sits without support', 'motor', 'clinical',
   21, 26, 34,
   2, 'Independent sitting is a major milestone. It frees up the hands for play and exploration. It is also a key safety marker for moving to a high chair and starting more complex solid foods.', '* Transition practice to a flat, firm surface without pillows nearby (but stay close)
* Place toys in front of them to keep their attention while they balance
* Once they are steady, practice reaching while sitting to build core stability',
   'They will still topple over occasionally when they get excited or distracted. This is normal until around 9 months.', 'If your baby is not sitting independently by 8 months, mention it at your well child visit.', 'WHO Motor Milestones; CDC',
   NULL, FALSE, TRUE),
  ('motor-stacking-blocks-3', 'Fine motor: stacks 2–3 blocks', 'motor', 'clinical',
   52, 56, 69,
   2, 'Stacking requires a steady hand, depth perception, and the ability to release an object intentionally. Stacking 2 to 3 blocks by 15 months is a standard fine motor checkpoint.', '* Provide 1 inch wooden or plastic blocks
* Sit on the floor and build a tower, then let the child try
* Celebrate the knock down just as much as the build',
   'They will prefer knocking your towers down for much longer than they will enjoy building their own. This is also a cognitive milestone (cause and effect).', 'If your 16 month old cannot stack two blocks, bring it up at the next visit.', 'CDC; Denver II',
   NULL, FALSE, TRUE),
  ('motor-stacking-blocks-6', 'Fine motor: stacks 6+ blocks', 'motor', 'clinical',
   65, 78, 91,
   2, 'By 18 to 21 months, the precision and patience required to stack 6 blocks shows advanced fine motor control and spatial awareness.', '* Continue providing blocks of different shapes and sizes
* Challenge them: How high can it go?
* Introduce simple puzzles with knobs',
   'Frustration is common. If the tower falls, they might have a small tantrum. Use this to practice co regulation.', 'If your 2 year old cannot stack more than 2 or 3 blocks, mention it at the 24 month visit.', 'CDC; Help Me Grow',
   NULL, FALSE, TRUE),
  ('motor-stair-climbing', 'Stair climbing with support', 'motor', 'advisory',
   56, 65, 78,
   3, 'Climbing stairs (with support, one step at a time) typically develops around 13 to 15 months alongside walking consolidation. It requires balance, coordination, and enough leg strength to lift body weight onto a higher step. Going up stairs comes before going down stairs, descending requires more motor control and spatial awareness.', '* Let them try stairs with your hand or a railing for support
* Go up together, step by step, narrating: "up, up, up"
* Do not carry them past stairs if they want to try, the practice is valuable
* Keep safety gates in place for unsupervised access until they are reliably safe',
   'Most children use both hands and both feet (crawling up stairs) before they walk up one step at a time. This is the normal progression.', 'If your 18 month old cannot ascend even one step with support, raise it at the 18 month visit alongside other gross motor observations.', 'CDC Milestones; AAP',
   NULL, FALSE, TRUE),
  ('motor-swaddle-stop', 'Stop swaddling when rolling signs appear', 'motor', 'advisory',
   12, 14, 17,
   1, 'A swaddled baby who rolls face down cannot push themselves back up or move their face away from the mattress. This is a suffocation risk. The AAP is unambiguous: stop swaddling the moment your baby shows any signs of rolling, attempting to roll, rocking side to side, or getting one shoulder off the mat during tummy time. Most babies show these signs between 2 and 4 months.', '* Watch for rolling signs during tummy time: rocking onto one shoulder, getting a knee under the body
* The day you see a rolling attempt: stop swaddling that night, cold turkey
* Transition options: a sleep sack (arms free), a wearable blanket, or nothing, all are safe. Some babies need a few rough nights to adjust.',
   'Sleep will get worse before it gets better when you drop the swaddle. This is temporary. The safety benefit is not worth compromising.', 'If your baby is already rolling and still being swaddled, stop tonight. This is not a gradual transition, it''s a safety call.', 'AAP Safe Sleep Guidelines (2022); SIDS and Other Sleep Related Infant Deaths: Evidence Base for 2016 Updated Recommendations (Pediatrics)',
   NULL, FALSE, TRUE),
  ('motor-tummy-time-build', 'Tummy time — build to 20 minutes/day', 'motor', 'advisory',
   0, 8, 17,
   1, 'Twenty minutes of tummy time per day by 4 months is the AAP recommendation, not all at once, but spread across the day. This is the foundation for rolling, which typically happens between 3 and 5 months. Without adequate tummy time, motor development slows down and the risk of positional flat head increases with each passing week.', '* Build gradually: add 1–2 minutes per week starting from wherever you are
* Break it into sessions: 4–5 sessions of 4–5 minutes each is as good as one long session
* Toys, mirrors, and siblings make it more tolerable, try a rolled towel under the chest for support',
   'Not all 20 minutes need to happen on the floor. Tummy time on a parent''s chest, lap, or forearm counts toward the daily total.', 'If you''re approaching 4 months without consistent tummy time, start immediately with short bursts and build fast. The motor development window is still open, but the sooner you start building the total daily minutes, the better.', 'AAP Safe to Sleep Campaign; WHO Motor Development Milestones',
   NULL, FALSE, TRUE),
  ('motor-tummy-time-start', 'Tummy time — start from birth', 'motor', 'advisory',
   0, 0, 12,
   1, 'Tummy time builds the neck, shoulder, and back muscles your baby needs for every physical milestone that follows, rolling, sitting, crawling, standing. It also prevents positional flat head (plagiocephaly), which is almost entirely preventable in the first months and significantly harder to address after 6 months. With First Son, I started tummy time late because he hated it and I caved. He developed mild flat head that took months to correct. With Second Son I started at day three and was consistent from the beginning. The difference was significant.', '* Start the first week home from the hospital: 2–3 minutes, 2–3 times per day
* Use your chest, lay baby face down on your chest when you''re reclined. It counts
* Right after a diaper change is a natural moment to try',
   'Babies hate tummy time. This is normal. Discomfort does not mean harm. The goal is tolerance, not enjoyment.', 'If tummy time hasn''t been happening consistently, start now. It''s not too late before 3 months. Go slowly, build up in 30 second increments, and use the chest position if the floor is resisted.', 'AAP Safe to Sleep Campaign; AAP Policy on Tummy Time (2021)',
   NULL, FALSE, TRUE),
  ('motor-walking-independent', 'Walking independently', 'motor', 'clinical',
   47, 56, 65,
   1, 'Independent walking, not just a few steps, but a primary mode of locomotion, typically establishes between 12 and 15 months. By 15 months, most children are walking well. Not walking independently by 15 months is a red flag that the AAP flags for assessment at the 15 month well child visit. Early identification of gross motor delays allows for early intervention, which produces significantly better outcomes.', '* Barefoot or soft sole shoes on hard floors is better for developing balance than stiff shoes
* Limit time in bouncers, walkers, and jumpers, they bypass the muscle groups needed for walking
* If walking hasn''t started by 13 months: mention it at your next visit, don''t wait for the scheduled appointment if you''re concerned',
   'Walking style varies enormously in the first months. Tip toe walking, wide stance, and wobbling are normal up to 18 months. The question is not how they walk, it''s whether they''re walking.', NULL, 'CDC Developmental Milestones (2022); AAP 15 Month Well Child Visit Guidelines; WHO Motor Milestone Windows',
   NULL, FALSE, TRUE),
  ('nutrition-2pct-milk-switch', 'Switch from whole to 2% milk at age 2', 'nutrition', 'advisory',
   104, 104, 117,
   3, 'Whole milk is recommended from 12 to 24 months because the fat content supports brain development. After age 2, the AAP recommends switching to 2% reduced fat milk (or continuing whole milk if the child is at risk of being underweight). The switch is a single decision and requires no transition period.', '* At the 24 month visit, confirm with your pediatrician that your child''s growth is on track for the switch
* Simply buy 2% from the next purchase, most children do not notice the difference
* If the child is lean or has slow weight gain, your pediatrician may recommend continuing whole milk',
   '2% milk is still a whole food with significant protein, fat, and calcium. It is not skim milk. The nutritional difference is modest.', 'If your 3 year old is still on whole milk and growing well, switching to 2% at any point is appropriate.', 'AAP Nutrition Guidelines; USDA Dietary Guidelines (2020)',
   NULL, FALSE, TRUE),
  ('nutrition-3-meals-rhythm', 'Move to 3 meals + 2 snacks daily', 'nutrition', 'advisory',
   34, 43, 52,
   2, 'By 10 months, solids should be becoming a significant part of the daily calorie count. Establishing a 3 meal rhythm prepares the baby for the transition away from formula or heavy breastfeeding at 12 months. It sets a predictable metabolic schedule.', '* Align baby meal times with the family schedule where possible
* Offer a variety of food groups at each meal: protein, fat, and fiber
* Start offering small healthy snacks between meals if baby seems hungry',
   'Some days they will eat everything, and some days they will eat nothing. Trust their internal hunger cues.', 'If your 12 month old is still only eating one real meal a day, they are likely over reliant on milk. Increase to 3 meals this week to ensure they get the nutrients they need.', 'USDA Dietary Guidelines for Infants; AAP',
   NULL, FALSE, TRUE),
  ('nutrition-bottle-intro-breastfed', 'Introduce a bottle — breastfed babies only', 'nutrition', 'advisory',
   3, 6, 16,
   1, 'The window for introducing a bottle to a breastfed baby without a fight is roughly weeks 3 to 16. Before 3 weeks, it can interfere with establishing breastfeeding. After 16 weeks, many babies simply refuse, they''ve developed a strong preference and lack the flexibility to switch. Miss this window and you''ve potentially lost all flexibility: every feed, every night, for as long as you breastfeed.', '* Introduce one bottle of expressed breast milk per day, starting around week 4–6
* Have someone other than the breastfeeding parent offer it, baby associates the smell of the nursing parent with the breast
* Don''t panic if the first attempt fails; try again the next day',
   'One or two rejected attempts early on don''t mean the window has closed, persistence in the first few weeks almost always works.', 'The window has likely closed, but it''s not impossible. Try a slow flow nipple, try different bottle shapes, and have your partner offer the bottle while you leave the room entirely. Some babies will accept a bottle at 5–6 months if you''re persistent. Others won''t. If flexibility is important, try for 2–3 weeks before accepting it may not happen.', 'AAP Policy on Breastfeeding and the Use of Human Milk (2022); Academy of Breastfeeding Medicine',
   NULL, FALSE, TRUE),
  ('nutrition-bottle-weaning', 'Wean off the bottle — transition fully to cup', 'nutrition', 'advisory',
   47, 52, 65,
   2, 'The AAP recommends being completely off the bottle by 15 months. Prolonged bottle use is a leading cause of tooth decay and can interfere with the development of the jaw and speech muscles. It also leads to excessive milk intake, which displaces essential solid foods.', '* Drop the midday bottles first, replacing them with a cup of milk or water during meals
* Drop the morning bottle next
* The before bed bottle is usually the hardest and should be the last to go',
   'A few days of protest are normal. Comfort the child with a book or a snuggle instead of the bottle to build a new routine.', 'If your 18 month old is still on a bottle, it is time for a firm transition. Replace all bottles with straw or open cups this weekend.', 'AAPD; AAP Section on Oral Health',
   NULL, FALSE, TRUE),
  ('nutrition-breastfeeding-establishment', 'Breastfeeding establishment — the first 8 weeks', 'nutrition', 'advisory',
   0, 1, 8,
   2, 'The first 8 weeks are the critical window for supply and demand. Your body is calibrating how much milk to make based on how often the baby removes it. Frequent, effective removal in these weeks sets the stage for the rest of your breastfeeding journey. This is often the hardest period.', '* Nurse on demand, usually 8-12 times per 24 hour period
* Ensure a deep latch to prevent nipple pain and ensure milk transfer
* Avoid long stretches without nursing or pumping in the first month',
   'Cluster feeding, where baby wants to eat every hour, is normal and does not mean your supply is low. It is the baby''s way of telling your body to make more milk.', 'If you are struggling at week 4 or 6, it is not too late. Contact a lactation consultant immediately. Many supply issues can be corrected with proper support before the 8 week mark.', 'Academy of Breastfeeding Medicine; AAP Policy',
   'getfamilyforce.com/playbook-feeding', FALSE, TRUE),
  ('nutrition-choking-hazards', 'Know the choking hazard list — update at 12 months', 'nutrition', 'advisory',
   0, 52, 65,
   2, 'As toddlers get more mobile and independent, they are more likely to put small objects in their mouths. At 12 months, they are also eating more adult foods. Choking remains a leading cause of accidental death in this age group.', '* Cut grapes and cherry tomatoes lengthwise into quarters
* Avoid whole nuts, popcorn, hard candy, and large chunks of meat or hot dogs
* Ensure all toys are choke tested (too large to fit through a toilet paper roll)',
   'Gagging is still normal as they learn new textures. Stay calm and watch for the difference: a choking child is silent and cannot breathe.', 'Review your home and your kitchen today. This is a rule that stays active through age 4.', 'AAP; Safe Kids Worldwide',
   NULL, FALSE, TRUE),
  ('nutrition-cows-milk-switch', 'Switch to whole cow''s milk at 12 months', 'nutrition', 'advisory',
   52, 52, 56,
   2, 'At one year, most babies can digest the proteins in cow milk and no longer need formula or exclusive breast milk. Whole milk provides the specific fats needed for brain development through age two. Do not switch earlier, as infant kidneys cannot handle the protein load of cow milk before 12 months.', '* Transition gradually: mix 1/4 milk with 3/4 formula for a few days, then 1/2 and 1/2
* Use full fat (whole) milk, not 2% or skim
* If there is a family history of dairy allergy, consult your pediatrician before the switch',
   'If you are still breastfeeding, you do not need to add cow milk. Breast milk continues to provide excellent nutrition. Cow milk is simply a substitute for formula at this stage.', 'If your 13 month old is still on formula, you are spending more money than necessary. Switch to whole milk this week unless your doctor gave specific medical instructions otherwise.', 'AAP; USDA',
   NULL, FALSE, TRUE),
  ('nutrition-dairy-intro', 'Introduce dairy (yogurt/cheese) — early allergen', 'nutrition', 'advisory',
   17, 26, 39,
   2, 'While babies should not drink cow milk as a beverage until 12 months, they can and should have dairy products like yogurt and cheese starting around 6 months. This early exposure helps prevent milk protein allergies.', '* Offer plain, full fat Greek yogurt (no added sugar)
* Provide small pieces of pasteurized, mild cheese
* Monitor for skin rashes or excessive spitting up',
   'The digestive system can handle the proteins in yogurt and cheese much better than the proteins in a glass of milk. These are safe first foods.', 'If you are past 9 months, start with plain yogurt today. Full fat dairy is important for brain development in the second half of the first year.', 'AAP Infant Food and Feeding; USDA',
   NULL, FALSE, TRUE),
  ('nutrition-dental-diet', 'Limit sugar — dental health starts with diet', 'nutrition', 'advisory',
   26, 52, 156,
   3, 'Dental caries (cavities) is the most common chronic disease in children. Sugar, combined with oral bacteria, produces acid that destroys enamel. Baby teeth matter, early cavity patterns predict adult cavity risk and affect speech development, nutrition, and comfort. Diet is the most controllable variable.', '* Avoid added sugars under 2 years entirely (AAP recommendation)
* After 2, limit added sugar to less than 25g (6 tsp) per day
* Never put a baby to bed with a bottle of juice or milk, the sugar pools around teeth throughout the night
* Brush teeth twice daily as soon as the first tooth appears',
   'Naturally occurring sugars in whole fruit are different from added sugars. Whole fruit with fiber slows glucose absorption and is not the dietary concern here.', 'The first dental visit should happen when the first tooth appears or by age 1, whichever comes first. If you have not been yet, schedule it now.', 'AAP Oral Health Policy; AAPD Caries Prevention Guidelines; WHO Sugar Guidelines',
   NULL, FALSE, TRUE),
  ('nutrition-egg-intro', 'Introduce eggs — early allergen', 'nutrition', 'advisory',
   17, 26, 39,
   1, 'Egg is the second most common food allergy in children after peanut. The same early introduction research that changed peanut guidelines also applies to eggs: introducing eggs during the solid food window (4–9 months) significantly reduces the likelihood of egg allergy developing. The immune system is most flexible during this period.', '* Introduce well cooked egg (scrambled or hard boiled) first, raw or undercooked egg carries salmonella risk
* Mix a small amount into puree on day one; give alone on day two and three
* Watch for 20 minutes after first introduction; a mild rash around the mouth can be normal and doesn''t indicate allergy
* If no reaction after 3 days, eggs can become a regular part of the diet',
   'Egg yolk and egg white have different allergen profiles. Most guidance now recommends introducing both together. If your child tolerates one and not the other, that''s worth noting but not cause for alarm before talking to your pediatrician.', 'Eggs can still be introduced after 9 months. The early introduction benefit applies most strongly before this window, but food allergies to eggs can still be avoided. Introduce normally and watch for reactions.', 'AAP Infant Food and Feeding Guidelines (2022); LEAP On Study; Australasian Society of Clinical Immunology and Allergy (ASCIA)',
   NULL, FALSE, TRUE),
  ('nutrition-family-foods', 'Integrate family foods — eat what everyone eats', 'nutrition', 'advisory',
   47, 52, 65,
   2, 'By 12 months, the baby food phase should be ending. Eating the same healthy foods as the rest of the family encourages social development and prevents the short order cook syndrome where parents make separate meals for toddlers.', '* Modify the family meal: cut it into safe pieces and skip the added salt or sugar
* Include the child at the dinner table with everyone else
* Exposure to the scents and sights of family meals builds a broader palate',
   'Toddlers are naturally skeptical of new foods. It can take 10 to 15 exposures before they actually try something. Keep putting it on the plate without pressure.', 'If you are still buying special jars of baby food at 14 months, stop. Serve small portions of your own healthy dinner tonight.', 'AAP Healthy Active Living; USDA',
   NULL, FALSE, TRUE),
  ('nutrition-first-purees', 'First solids: single-ingredient purees', 'nutrition', 'advisory',
   17, 26, 30,
   2, 'The goal of first solids is exposure and safety. Single ingredient purees allow you to identify any allergic reactions or sensitivities easily. At this stage, breast milk or formula is still the primary nutrition. Food is for practice.', '* Start with smooth purees of vegetables or fruits like sweet potato, avocado, or peas
* Introduce only one new food every 3-4 days
* Watch for rashes, vomiting, or diarrhea after each new food',
   'Most of the first few meals will end up on the floor or the bib. This is expected. A few teaspoons is a successful meal at this age.', 'If you are past 6 months and haven''t tried purees, start today. Variety is important for developing a palate and preventing picky eating later.', 'CDC Infant and Toddler Nutrition; AAP',
   NULL, FALSE, TRUE),
  ('nutrition-fish-intro', 'Introduce fish — early allergen', 'nutrition', 'advisory',
   17, 26, 39,
   2, 'Fish is a common allergen, but early introduction (before 9 months) is now recommended to reduce the risk of developing a lifelong allergy. Fish also provides DHA, which is essential for brain and eye development.', '* Offer well cooked, pureed or flaked white fish like cod or salmon
* Ensure there are absolutely no bones
* Give it alone for 3 days to monitor for reactions before mixing with other foods',
   'Avoid high mercury fish like swordfish or king mackerel. Stick to salmon, trout, and cod which are safe for infants.', 'If you missed the 9 month window, introduce fish as soon as possible. The protective effect against allergies is strongest early, but introduction is still beneficial.', 'AAP Healthy Active Living for Families; NIAID Guidelines',
   NULL, FALSE, TRUE),
  ('nutrition-fork-intro', 'Fork introduction', 'nutrition', 'advisory',
   65, 78, 104,
   3, 'Fork use typically emerges between 15 and 24 months. The stabbing motion of a fork is easier to master than the scooping of a spoon, which often means forks become the preferred utensil quickly once introduced. Toddler forks are blunt and safe for independent use.', '* Introduce a toddler fork alongside the spoon at mealtimes
* Foods that hold to a fork easily (soft pasta, cooked vegetables, cheese cubes) work well at first
* Let them stab independently, even if they hold the fork awkwardly',
   'Using a fork with the whole fist grip is normal through age 3. A mature pencil like grip develops much later.', 'If your 2 year old has no interest in utensils at all, it is worth noting at the 24 month visit.', 'AAP; CDC',
   NULL, FALSE, TRUE),
  ('nutrition-healthy-snack-patterns', 'Build healthy snack patterns before age 2', 'nutrition', 'advisory',
   52, 65, 104,
   3, 'Eating patterns established in the first two years predict eating habits in later childhood. Research consistently shows that repeated exposure to a diverse range of foods in the toddler years (even if rejected at first) produces broader dietary acceptance by school age. The toddler who only eats beige food is often the child who was not consistently offered variety early.', '* Offer 2 to 3 planned snacks per day at predictable times, unplanned grazing disrupts hunger cues
* Include a protein and a fruit or vegetable at each snack
* Continue offering foods that have been rejected, it can take 10 to 15 exposures before a food is accepted',
   'Toddler food refusal is normal. The goal is continued exposure, not compliance. A refused food on the plate is still doing its job.', 'If your 2 year old eats fewer than 10 different foods regularly, consider speaking to your pediatrician or a pediatric dietitian about expanding variety.', 'Birch and Fisher (1998), Food Acceptance Patterns; AAP; USDA MyPlate',
   NULL, FALSE, TRUE),
  ('nutrition-honey-avoidance', 'No honey under 12 months (botulism risk)', 'nutrition', 'advisory',
   0, 0, 52,
   2, 'Honey can contain spores of Clostridium botulinum, which can cause infant botulism. A baby''s digestive system is not developed enough to stop these spores from growing and producing toxins. This is rare but can be fatal.', '* Absolutely no honey in any form: raw, baked into crackers, or in tea
* Check labels of processed snacks for honey content
* Once the child turns one, their digestive system is mature enough to handle it safely',
   'If a family member accidentally gives a tiny taste, monitor for signs like constipation, weak crying, or muscle weakness and call your doctor. Most exposures do not lead to illness, but the risk is not worth taking.', 'This is a safety rule that stays in effect until the first birthday. After 12 months, honey is safe to introduce.', 'CDC; AAP; WHO',
   NULL, FALSE, TRUE),
  ('nutrition-iron-fortified-foods', 'Introduce iron-fortified foods with first solids', 'nutrition', 'advisory',
   17, 26, 34,
   2, 'Around 6 months, a baby''s natural iron stores are almost gone. Because brain development is rapid, iron is a non negotiable nutrient. Iron fortified cereals or pureed meats are the most efficient way to fill the gap.', '* Choose iron fortified infant cereals like oat or barley
* Pureed meats (beef, chicken, turkey) are excellent natural sources of iron and zinc
* Mix cereal with breast milk or formula to increase acceptance',
   'Rice cereal was the old standard, but it is no longer recommended as a primary food due to arsenic concerns. Stick to oat or multigrain options.', 'If your baby is 8 months and only eating fruits and vegetables, they may be low on iron. Prioritize meat or fortified cereal starting with the next meal.', 'AAP Clinical Report on Iron Deficiency; USDA Dietary Guidelines',
   NULL, FALSE, TRUE),
  ('nutrition-iron-rich-ongoing', 'Keep iron-rich foods in regular rotation', 'nutrition', 'advisory',
   26, 52, 156,
   3, 'Iron deficiency is the most common nutritional deficiency in young children globally. After the iron stores from birth are depleted (around 6 months), dietary iron becomes critical. Toddlers who drink more than 24 oz of cow''s milk per day are at elevated risk for iron deficiency because milk displaces iron rich foods and reduces iron absorption.', '* Include iron rich foods daily: red meat, beans, lentils, fortified cereals, tofu, dark leafy greens
* Pair non heme iron sources (plant based) with vitamin C to increase absorption: beans with tomato, spinach with lemon
* Limit cow''s milk to 16 to 24 oz per day',
   'Occasional meals without iron rich foods are fine. The concern is a pattern of dairy heavy, iron light eating across days and weeks.', 'At the 12 and 24 month visits, your pediatrician should check hemoglobin. If iron deficiency is found, dietary change is the first line intervention.', 'AAP Iron Supplementation Policy; WHO Iron Deficiency Anemia Guidelines',
   NULL, FALSE, TRUE),
  ('nutrition-iron-supplement-breastfed', 'Iron supplementation — breastfed babies at 4 months', 'nutrition', 'advisory',
   17, 17, 26,
   1, 'Breast milk is nearly perfect nutrition, but it''s low in iron. Babies are born with iron stores that last about 4 to 6 months. After that, those stores run out, and breast milk doesn''t replenish them fast enough. Iron deficiency in the first year affects brain development, cognitive function, and behavior, and it''s one of the most preventable nutritional problems in infancy.', '* At the 4 month well child visit, ask your pediatrician about starting liquid iron drops (1 mg/kg/day is the AAP recommendation for breastfed infants)
* Continue until iron rich solids are well established, usually around 6–7 months
* Formula fed babies don''t need this: iron fortified formula covers it',
   'Liquid iron drops stain, but they''re not harmful. The dark stools you may see are normal and not a sign of a problem.', 'If this window passed without action, bring it up at the next pediatrician visit. A simple blood test can check iron levels. If iron is low, supplementation and dietary intervention can correct it, the earlier the better.', 'AAP Clinical Report, Iron Deficiency and Iron Deficiency Anemia in Young Children (2020); CDC Iron Recommendations',
   NULL, FALSE, TRUE),
  ('nutrition-juice-limit', 'Limit juice — no juice under 12 months, max 4oz after', 'nutrition', 'advisory',
   0, 52, 104,
   3, 'The AAP recommends no fruit juice under 12 months and a maximum of 4 oz per day for children 12 to 36 months. Juice is high in sugar, low in fiber, and displaces more nutritious foods and drinks. Children who drink juice regularly are at higher risk for dental caries and excessive caloric intake.', '* Under 12 months: no juice at all. Water and breast milk or formula only.
* Ages 1 to 3: if offered, limit to 4 oz per day in a cup (not a sippy that they carry all day)
* Whole fruit is always a better option than fruit juice',
   'An occasional small amount of juice is not going to cause harm. The concern is habitual juice intake replacing more nutritious options.', 'If your toddler has been drinking significant amounts of juice daily, reducing gradually over a few weeks is more effective than stopping abruptly.', 'AAP Fruit Juice Policy (2017); Pediatrics',
   NULL, FALSE, TRUE),
  ('nutrition-milk-cap', 'Cap milk at 16–24 oz/day after 12 months', 'nutrition', 'advisory',
   52, 52, 65,
   2, 'After age one, too much milk is a problem. It fills the stomach so the child doesn''t eat enough solid food, which leads to iron deficiency anemia. Milk is also low in fiber, so milk babies often struggle with severe constipation.', '* Limit total milk intake (cow milk or breast milk) to no more than 24 ounces in a 24 hour period
* Water should be the primary drink for thirst between meals
* If your child demands more milk, offer a small snack or water instead',
   'The transition might feel like the child isn''t getting enough at first. As long as they are eating a variety of solid foods, they are fine.', 'If your toddler is drinking 30 or more ounces of milk a day, cut back by 4 ounces every two days until you are under the 24 ounce limit.', 'AAP; USDA',
   NULL, FALSE, TRUE),
  ('nutrition-peanut-intro', '⚠️ Peanut introduction window', 'nutrition', 'clinical',
   17, 20, 47,
   1, 'The LEAP study, published in the New England Journal of Medicine in 2015, showed that introducing peanuts between 4 and 11 months reduces the risk of peanut allergy by up to 80%. This is one of the most significant preventive health findings in pediatric research in a generation. The old advice was to avoid peanuts. The new advice is the opposite: introduce them early, and introduce them often. The window closes at 11 months.', '* If your child has no eczema and no known food allergies: introduce at home, no doctor visit required
* If your child has mild to moderate eczema: consult your pediatrician first, they may recommend an allergy test
* Method: mix 1/4 teaspoon of smooth peanut butter into fruit or vegetable puree. Start with a small amount on a spoon, wait 20 minutes, watch for reactions (hives, swelling, vomiting, difficulty breathing)
* If no reaction: offer peanut products 3 times per week going forward to maintain tolerance',
   'You don''t need an allergist appointment unless your child has severe eczema or a known egg allergy. Most children can be introduced at home with no special preparation.', NULL, 'Du Toit et al. (2015), LEAP Study, New England Journal of Medicine; AAP Updated Guidance on Early Peanut Introduction (2017); NIAID Addendum Guidelines (2017)',
   NULL, FALSE, TRUE),
  ('nutrition-self-feeding-pincer', 'Self-feeding with pincer grasp', 'nutrition', 'advisory',
   34, 39, 52,
   3, 'The pincer grasp (picking up small objects with thumb and index finger) typically develops around 8 to 10 months. Soft, small finger foods at this stage are both a feeding strategy and a fine motor practice opportunity. Babies who are allowed to self feed small pieces develop better hand coordination and show more positive relationships with food.', '* Offer soft, small pieces of food at mealtimes alongside purees: peas, soft banana, cooked carrot pieces, small pasta
* Let them pick up and eat independently, even if it takes a long time
* Always supervise and ensure pieces are small enough to dissolve safely',
   'Most of the food will end up on the floor. Self feeding at this age is about motor practice and food exposure as much as nutrition.', 'If your 12 month old is not attempting to pick up small pieces of food at all, mention it at the 12 month visit alongside other fine motor observations.', 'AAP Complementary Feeding Guidelines; Baby Led Weaning Research (Rapley and Murkett)',
   'getfamilyforce.com/playbook-feeding', FALSE, TRUE),
  ('nutrition-sesame-intro', 'Introduce sesame — early allergen', 'nutrition', 'advisory',
   17, 26, 39,
   2, 'Sesame was recently added to the list of major allergens because reactions can be severe. Like other allergens, the window for safe introduction is during the first year of life.', '* Hummus or tahini thinned with water or puree is the easiest way to introduce sesame
* Do not give whole sesame seeds as they are a choking hazard
* Monitor for 20 minutes after the first few exposures',
   'Tahini has a strong taste. If baby rejects it at first, try mixing a tiny amount into a puree they already like.', 'If your baby is over 9 months and hasn''t had sesame, add it to the menu this week.', 'FASTER Act (2021); AAP Guidelines',
   NULL, FALSE, TRUE),
  ('nutrition-sippy-cup', 'Sippy/straw cup introduction', 'nutrition', 'advisory',
   26, 34, 47,
   2, 'Learning to use a cup is a motor skill that prevents the dental and speech issues associated with long term bottle use. Starting at 6 months with small sips of water prepares them to be fully off the bottle by their first birthday.', '* Offer a straw cup or an open cup with a tiny amount of water at meal times
* Weighted straw cups are often easier for babies to learn than traditional sippy cups
* Be patient: it takes weeks of practice before they actually swallow more than they spill',
   'The mess is part of the learning process. Use a bib and a waterproof mat.', 'If your baby is 10 months and has never used a cup, start today. Transitioning after 12 months is significantly harder as the emotional attachment to the bottle grows.', 'AAPD Dental Health Guidelines; AAP',
   NULL, FALSE, TRUE),
  ('nutrition-solids-readiness', 'Watch for solid food readiness signs', 'nutrition', 'advisory',
   17, 21, 26,
   2, 'Starting solids is about developmental readiness, not just age. Most babies are ready around 6 months. Starting too early (before 4 months) is linked to obesity and digestive issues. Starting too late (after 7 months) can lead to iron deficiency and texture aversion.', '* Look for: sitting with little support, good head control, and interest in what you are eating
* Watch for the loss of the tongue thrust reflex, when baby stops pushing objects out of their mouth with their tongue
* If baby reaches for your food and can hold their head steady, they are likely ready',
   'If your baby is 5 months and shows no interest, that is fine. The 6 month mark is the standard goal for most.', 'If your baby is 7 months and has not started solids, begin this week. Iron stores are depleting and they need the nutrients from food.', 'WHO Guidelines on Complementary Feeding; AAP Section on Breastfeeding',
   NULL, FALSE, TRUE),
  ('nutrition-soy-intro', 'Introduce soy — early allergen', 'nutrition', 'advisory',
   17, 26, 39,
   3, 'Soy is one of the top 9 allergens. The LEAP and EAT studies established that early introduction of allergens reduces the likelihood of allergy development. Soy can be introduced alongside other allergens between 4 and 6 months when solids begin.', '* Introduce soy through age appropriate foods: soft tofu, edamame pureed, or very small amounts of soy based formula as a supplemental taste
* Introduce at home (not daycare) when you have time to monitor for 1 to 2 hours
* If there is a family history of soy or legume allergy, check with your pediatrician first',
   'Soy allergy affects only about 0.4% of children. Most children tolerate soy easily. The purpose of early introduction is prevention, not diagnosis.', 'If you delayed soy introduction past 9 months, introduce it now with standard allergen introduction precautions.', 'LEAP Study (Du Toit et al. 2015); AAP Allergen Introduction Guidelines',
   NULL, FALSE, TRUE),
  ('nutrition-spoon-self-feeding', 'Spoon self-feeding — let them try', 'nutrition', 'advisory',
   52, 65, 78,
   3, 'Spoon self feeding typically begins around 12 to 15 months. It is messy, inefficient, and completely normal. The fine motor coordination required to scoop and bring a spoon to the mouth without tipping it takes months to develop. Interrupting the attempt to feed them yourself sends a message that they cannot do it, and also delays the motor development.', '* Load the spoon for them in the early weeks and hand it to them, they manage the transport
* Use a wide, shallow spoon designed for toddlers
* Accept the mess. A splat mat under the chair is a practical long term investment.',
   'A 15 month old eating mostly with their hands despite having a spoon available is completely normal. The spoon skill takes months to consolidate.', 'If your 2 year old shows no interest in or ability to use a spoon at all, mention it at the 24 month visit as part of fine motor review.', 'AAP; CDC Motor Milestones',
   'getfamilyforce.com/playbook-feeding', FALSE, TRUE),
  ('nutrition-texture-finger-foods', 'Texture progression: soft finger foods', 'nutrition', 'advisory',
   30, 34, 43,
   2, 'Soft finger foods develop the pincer grasp and self regulation. Babies who feed themselves learn to stop when they are full, which is a foundational habit for healthy weight. This window typically opens around 7 to 8 months.', '* Offer pea sized pieces of very soft food: cooked carrots, ripe pear, or small pieces of tofu
* The food should be soft enough to mash between your thumb and forefinger
* Always supervise finger food sessions closely',
   'You do not need teeth to eat soft finger foods. Gums are incredibly strong and can handle most well cooked vegetables.', 'If your 11 month old is not yet eating finger foods, start with very soft puffs or small bits of banana today. Self feeding is a major milestone for independence.', 'CDC Infant Nutrition; UNICEF',
   NULL, FALSE, TRUE),
  ('nutrition-texture-mashed', 'Texture progression: mashed and lumpy foods', 'nutrition', 'advisory',
   26, 30, 39,
   2, 'There is a critical window between 6 and 9 months where babies are most open to new textures. If you stay on smooth purees for too long, you risk texture aversion, where the child refuses lumpy or solid food later. This is a primary cause of picky eating in toddlers.', '* Stop blending food into a liquid: use a fork to mash soft foods like banana or avocado
* Gradually increase the size of the lumps as baby gets better at chewing (even without teeth)
* Introduce Stage 3 thicker baby foods if using store bought options',
   'Gagging is a normal safety reflex. It is not the same as choking. If baby gags, stay calm and let them work the food forward with their tongue.', 'If your 10 month old refuses anything but smooth purees, you must move to mashed textures immediately. It will be a struggle for a few days, but the longer you wait, the harder it gets.', 'WHO Complementary Feeding Study; Illingworth (1986)',
   NULL, FALSE, TRUE),
  ('nutrition-tree-nut-intro', 'Introduce tree nuts — early allergen', 'nutrition', 'advisory',
   17, 26, 39,
   1, 'Tree nut allergies, cashew, almond, walnut, pistachio, are among the most common causes of severe allergic reactions in children, and they tend to be lifelong. Like peanut and egg, early introduction during the solid food window reduces the likelihood of allergy developing. Tree nuts are not the same as peanuts (peanuts are legumes), so peanut tolerance does not mean tree nut tolerance.', '* Introduce as a thinned nut butter (almond or cashew butter thinned with water or puree, never whole nuts, which are a choking hazard)
* Introduce one tree nut at a time, 3–4 days apart, so reactions can be traced
* Watch for 20 minutes after each first introduction
* Don''t rush: you don''t need to introduce all tree nuts in one week',
   'A mild rash around the mouth after tree nut introduction is often a contact reaction, not a true allergy. True allergic reactions involve hives, swelling, vomiting, or breathing difficulty. If unsure, call your pediatrician.', 'Tree nuts can still be introduced after 9 months with appropriate caution. Early introduction is preferred but not the only option.', 'AAP Infant Food and Feeding Guidelines (2022); ASCIA Early Introduction Guidelines',
   NULL, FALSE, TRUE),
  ('nutrition-vitamin-d-breastfed', 'Vitamin D drops — start from birth (breastfed)', 'nutrition', 'advisory',
   0, 1, 52,
   2, 'Breast milk is nearly perfect, but it is low in Vitamin D. Infants who do not get enough risk rickets, which is a condition that causes weak or deformed bones. Because babies should not have direct sun exposure in the first 6 months, they cannot make their own Vitamin D. Supplements are the only reliable source.', '* Give 400 IU of liquid Vitamin D drops once per day
* Place the drop directly on the nipple before a feed or in a small bottle of expressed milk
* Continue until your baby is drinking at least 32 ounces of Vitamin D fortified formula or whole milk daily',
   'If you miss a day, do not double the dose. Just resume the normal routine the next day. The benefit is cumulative over time.', 'If you have not started yet, start today. Most babies have enough stores to last a few weeks, but beginning as soon as possible prevents long term deficiency.', 'AAP Clinical Report, Vitamin D Status of Infants (2023)',
   NULL, FALSE, TRUE),
  ('nutrition-vitamin-d-formula', 'Confirm formula has vitamin D (formula-fed)', 'nutrition', 'advisory',
   0, 4, 52,
   3, 'Most commercial infant formulas are fortified with vitamin D. If your baby is formula fed with a standard commercially prepared formula, and drinking at least 32 oz per day, they are likely getting adequate vitamin D. The AAP recommendation for 400 IU/day is met by most full formula fed babies without drops. Check the label to confirm.', '* Read the nutrition label on your formula can, look for vitamin D in the IU per serving column
* If you are mixing formula with breast milk, calculate the proportion and supplement the difference
* Ask your pediatrician at the 4 month visit if you are unsure',
   'If your baby is drinking a full volume of standard commercial formula, additional vitamin D drops are generally not needed. Breastfed babies are the primary group requiring drops.', 'If you have been exclusively formula feeding and later discover the formula was not fortified, mention it at the next visit. Deficiency is unlikely with standard formula but worth noting.', 'AAP Vitamin D Policy; Pediatrics (2022)',
   NULL, FALSE, TRUE),
  ('nutrition-water-cup', 'Introduce water in a cup', 'nutrition', 'advisory',
   26, 26, 52,
   3, 'Small amounts of water (2 to 4 oz per day) can be introduced around 6 months when solids begin. Water with meals helps digestion and introduces the concept of a cup. Under 6 months, water is not recommended because it can displace breast milk or formula and cause electrolyte imbalance.', '* Use a small open cup or 360 cup, this is also good oral motor practice
* Offer at mealtimes alongside solids, not instead of breast milk or formula
* Amounts are small: a few sips is plenty at first',
   'Your baby will spill most of it. That is the expected outcome. The goal is exposure to the cup and a few sips of water, not hydration.', 'If your baby is 12 months and still on the bottle for all fluids, start cup practice now. The AAP recommends transitioning off the bottle entirely by 15 to 18 months.', 'AAP Nutrition Guidelines; Healthy Eating Research',
   NULL, FALSE, TRUE),
  ('nutrition-wheat-intro', 'Introduce wheat — early allergen', 'nutrition', 'advisory',
   17, 26, 39,
   2, 'Wheat is one of the top nine allergens. Introducing it between 4 and 9 months, ideally while still breastfeeding, can help the immune system learn to tolerate gluten. This reduces the risk of wheat allergy and potentially Celiac disease.', '* Start with a small amount of wheat cereal or a tiny piece of well cooked pasta
* Watch for any digestive distress or skin reactions
* If tolerated, keep wheat in the diet at least twice a week',
   'Gluten is not something to fear unless there is a diagnosed medical reason. For most babies, early exposure is a safety measure.', 'Introduce wheat now. If there is a family history of Celiac disease, talk to your doctor, but for most, delayed introduction actually increases risk.', 'NIAID Addendum Guidelines for Food Allergy Prevention',
   NULL, FALSE, TRUE),
  ('prebirth-hospital-bag', 'Pack the hospital bag', 'prebirth', 'advisory',
   6, 3, 0,
   2, 'A packed hospital bag at 37 weeks means one less thing to think about when labor starts. It also means you do not end up in the hospital without the things that actually matter: the car seat, the insurance card, the phone charger. First time parents typically underestimate how foggy and fast the immediate postpartum period is. Pack it now.', 'For the birth parent:
* Insurance card and ID
* Birth preferences document (keep it to one page)
* Phone charger and a portable battery
* Comfortable, loose clothing for labor and postpartum: a few changes, socks
* Toiletries: toothbrush, shampoo, dry shampoo, face wash, lip balm
* Nursing bra and breast pads if planning to breastfeed
* Snacks for labor: granola bars, electrolyte drinks (hospitals often restrict eating during active labor)
* Going home outfit (sized for 6 months postpartum, not your pre pregnancy size)

For the partner or support person:
* Phone charger
* Snacks and cash (hospital vending machines get expensive)
* A change of clothes
* Entertainment for the long stretches of early labor

For the baby:
* A going home outfit in newborn size AND 0 to 3 months (newborns are unpredictably sized)
* A hat and a swaddle blanket
* The car seat, installed and checked before 37 weeks (see below)

**Car seat: do this before you pack the bag:**
* Install the infant car seat in the car before 37 weeks
* Have the installation checked at a certified Child Passenger Safety Technician inspection station (most fire stations offer this free)
* The hospital will not let you leave without the baby in a correctly installed car seat',
   'You do not need a complete nursery ready before the baby comes home. You need: a safe place to sleep, the car seat, and enough supplies for 48 to 72 hours. The rest can wait.', 'If you are reading this at 38 or 39 weeks and the bag is not packed: do it this weekend. You may not get another clear window.', 'ACOG Labor and Delivery Preparation Guidelines; NHTSA Car Seat Safety; Safe Kids Worldwide',
   NULL, TRUE, TRUE),
  ('prebirth-newborn-screening', 'Understand newborn screening before the birth', 'prebirth', 'screening',
   4, 0, 1,
   1, 'Newborn screening is one of the most important public health programs in existence. Before you leave the hospital, your baby will be tested for dozens of rare but serious conditions: metabolic disorders, hormonal conditions, cystic fibrosis, critical congenital heart disease, hearing loss. Most of these conditions are invisible at birth. Early detection means early treatment, and for many of them early treatment is the difference between a normal life and a severely impacted one.

This is not optional and not something you need to worry about arranging. It happens automatically at the hospital. What you need to do is understand what it is so you are not blindsided if a result comes back.', 'Three screens happen automatically before you leave the hospital. Know what they are:

1. **Blood spot test (heel prick):** Done at 24 to 48 hours after birth. A few drops of blood from the baby''s heel, tested for up to 60+ conditions depending on your state or country. Results typically come back within 1 to 2 weeks. Your pediatrician will contact you if anything requires follow up.
2. **Hearing screen:** Done before discharge. A small probe in the ear, painless, takes a few minutes. If the baby does not pass initially, it is often due to fluid in the ear canal from birth. A rescreen is done before the first pediatrician visit.
3. **Critical Congenital Heart Disease (CCHD) screen:** Done after 24 hours of age. A pulse oximeter on the hand and foot measures oxygen levels. Low or discrepant readings trigger further evaluation.

Before you leave the hospital:
* Ask the staff whether all three screens were completed
* Confirm your pediatrician''s contact information is in the hospital record so they receive results directly

If a result flags:
* Do not panic. Most abnormal newborn screening results are false positives that resolve on repeat testing.
* Follow your pediatrician''s guidance immediately, including any specialist referral
* Act on it the same day if your pediatrician calls about a metabolic result — timeliness matters',
   'A rescreen for hearing is not a diagnosis of hearing loss. It is a standard protocol for a test that has a meaningful false positive rate in the first 24 hours of life.', 'If you left the hospital and are unsure whether all three screens were completed, call the hospital''s newborn nursery directly and ask. Your pediatrician should have the results in your file from the 3 to 5 day visit.', 'AAP Newborn Screening Policy; HRSA Recommended Uniform Screening Panel (RUSP); JCIH Position Statement (2019)',
   'getfamilyforce.com/playbook-screen-time', TRUE, TRUE),
  ('prebirth-pediatrician-selection', 'Choose your pediatrician before the baby is born', 'prebirth', 'advisory',
   10, 6, 0,
   1, 'The first well child visit happens within 3 to 5 days of birth. You will be exhausted, hormonally volatile, and trying to learn to feed a human. That is not the time to be researching doctors. Choosing your pediatrician before the birth means you have a name, a number, and an appointment already scheduled. It also means you have met this person before you are in crisis.

Many pediatric practices have prenatal meet and greet appointments (often called a prenatal consultation). They are worth doing.', '* Start looking at 28 to 32 weeks. Do not leave it past 35 weeks.
* Ask your OB, midwife, or trusted parents in your area for recommendations
* Narrow to 2 to 3 candidates and schedule prenatal consultations
* At the consultation, ask:
 * What are your after hours and weekend protocols?
 * What hospital are you affiliated with?
 * What is your approach to breastfeeding support?
 * What is your vaccine policy?
 * How long does it typically take to get a sick visit?',
   'You are not locked in forever. If the relationship does not work after 6 to 12 months, you can switch. But having someone chosen before the birth is substantially better than navigating newborn care without a doctor.', 'If the baby is already here and you do not have a pediatrician, call practices today and explain your situation. Most will prioritize a newborn appointment.', 'AAP Bright Futures Guidelines; ACOG Prenatal Care Guidelines',
   NULL, TRUE, TRUE),
  ('prebirth-safe-sleep-setup', 'Set up safe sleep before the baby arrives', 'prebirth', 'advisory',
   6, 4, 0,
   1, 'Safe sleep setup is one of the highest impact things you can do before your baby is born. Sudden Infant Death Syndrome (SIDS) and sleep related infant deaths are among the leading causes of death in the first year. The AAP''s safe sleep guidelines are clear and backed by decades of research. The time to set this up is before you are exhausted with a newborn in your arms, not after.

The ABCs: Alone, Back, Crib. Every sleep, every time, from day one.', '* Firm, flat sleep surface only. A crib, bassinet, or play yard with a firm mattress and fitted sheet. No inclined sleepers, no positioners, no nursing pillows left in the sleep space.
* Back to sleep for every single sleep, including naps. Once they can roll to their back independently (usually around 4 to 6 months), you do not need to reposition them. But always start them on their back.
* No loose items in the sleep space. No blankets, pillows, bumpers, stuffed animals. Nothing. A sleep sack instead of a blanket is the right call.
* Room sharing (not bed sharing) for at least the first 6 months. Your baby sleeps in their own sleep space, in your room. This reduces SIDS risk by up to 50% compared to a separate room.
* Temperature: 68 to 72 degrees Fahrenheit. Overbundling is a SIDS risk factor.',
   'The back sleeping position does not increase choking or aspiration risk. The gag reflex protects the airway. Healthy babies placed on their backs are safe.

If your baby falls asleep in a swing, car seat, or bouncer, move them to the flat sleep surface when you can. These surfaces are not safe for unsupervised sleep.', 'If the baby is already here and safe sleep is not in place, set it up today. It is never too late, and every sleep counts.', 'AAP Safe Sleep Policy (2022); CDC SIDS Data; Moon et al. Pediatrics (2022)',
   'getfamilyforce.com/playbook-sleep', TRUE, TRUE),
  ('safety-babyproofing', 'Babyproof the home — before crawling begins', 'safety', 'advisory',
   17, 26, 34,
   1, 'The window between birth and crawling (approximately 4–8 months) is the window to babyproof. Once a baby is mobile, and mobility happens faster than almost all first time parents expect, the hazard exposure multiplies overnight. Babyproofing takes an afternoon. An emergency room visit does not. The most dangerous household hazards for crawlers are: stairs, electrical outlets, cabinets containing cleaning products, unsecured furniture that can tip, and cords.', '* Get on your hands and knees and look at your home from baby''s height, this reveals hazards that aren''t visible from standing
* Priority targets: stair gates (top and bottom), outlet covers, cabinet locks for cleaning products and medications, furniture anchored to walls, electrical cords secured
* Check for small objects on floors that can be choking hazards',
   'You don''t need to buy everything at once. Start with the most dangerous hazards (stairs, toxins, tip over risks) and work outward from there.', 'If your baby is already crawling and the home isn''t babyproofed: start today, starting with the room where they spend the most time.', 'AAP Injury Prevention Guidelines; Safe Kids Worldwide, Home Safety Checklist; CDC Child Injury Prevention',
   NULL, FALSE, TRUE),
  ('safety-back-to-sleep', 'Back to sleep, every time — firm surface, no loose items', 'safety', 'advisory',
   0, 0, 26,
   1, 'Back sleeping reduces SIDS risk by 50%. The "Back to Sleep" campaign, launched in 1994, cut SIDS rates by more than 50% within a decade. The rule is absolute until 6 months: always on the back, for every sleep, every nap, every person who cares for this baby. Many SIDS deaths happen at grandparents'' houses or with babysitters who were raised differently and think "tummy sleeping is fine, we all did it."', '* Inform every caregiver: the rule is back sleeping, every time, no exceptions
* Tummy sleeping is safe during awake, supervised tummy time. Back sleeping is for sleep.
* After 6 months, when a baby can roll both ways independently, they can be left in whatever position they roll to, but still place them on their back to start',
   'Babies who are placed on their backs will not choke on spit up. The airway anatomy protects against this, a common misconception that leads parents to place babies on their sides "just in case."', 'The back to sleep rule applies until 6 months. After that, a baby who can roll independently can sleep in whatever position they roll to, but always start on the back.', 'AAP Safe Sleep Guidelines (2022); Moon et al., Back to Sleep Evidence Base; Pediatrics (2022)',
   'getfamilyforce.com/playbook-sleep', FALSE, TRUE),
  ('safety-car-seat-install-check', 'Car seat installation check — rear-facing, before birth/discharge', 'safety', 'advisory',
   0, 0, 4,
   1, 'Car accidents are the leading cause of injury death for children in the US. The first car ride, hospital to home, happens before most parents feel ready, and research shows that up to 75% of car seats are installed incorrectly. An incorrectly installed car seat in a crash provides substantially less protection. Installation needs to happen before the baby is born, not in the hospital parking lot.', '* Install the car seat rear facing before the due date, and have it checked
* Free car seat inspections are available at many fire stations and through Safe Kids Worldwide (safekids.org)
* The seat should not move more than 1 inch in any direction when you tug at the base',
   'You don''t need the most expensive car seat. The safest seat is any correctly installed seat that fits your vehicle and your child''s weight. Price does not predict safety rating.', 'If your baby is already here and the seat hasn''t been checked: get it checked before the next car trip. Most inspections take 15 minutes.', 'NHTSA Child Passenger Safety Guidelines (2024); AAP Car Seat Safety; Safe Kids Worldwide, Installation Statistics',
   NULL, FALSE, TRUE),
  ('safety-choking-awareness', 'Choking hazard list — know it and review it', 'safety', 'advisory',
   0, 17, 208,
   1, 'Choking is the leading cause of injury death in infants and one of the top causes in children under 4. The vast majority of choking incidents involve food or small objects that parents didn''t recognize as hazardous. The list is not intuitive: grapes, cherry tomatoes, hot dogs, whole nuts, raw carrots, popcorn, and raisins are all on it. So are coins, button batteries (which can cause severe internal burns within hours), and balloons. Most parents don''t know the full list.', '* Memorize the food hazard list: whole grapes, cherry tomatoes, hot dogs, nuts, raw carrots, popcorn, raisins, marshmallows, large chunks of any food
* Cut everything to pea size or smaller for under 4s, even soft foods
* Learn infant and child choking first aid alongside infant CPR (same class, usually)
* Button batteries are a separate critical hazard: if ingested, call poison control immediately',
   'Gagging is not choking. Babies gag frequently when learning to eat, it''s a safety reflex. The difference: a gagging child is making noise and is pink. A choking child is silent, has high pitched stridor, or is turning blue.', 'This window doesn''t close until age 4. Review the food list at major food transitions: starting solids (6 months), starting finger foods (8–9 months), and starting family foods (12 months).', 'AAP Choking Prevention Guidelines; Safe Kids Worldwide, Choking Hazard Data; National Capital Poison Center, Button Battery Guidelines',
   NULL, FALSE, TRUE),
  ('safety-crib-to-bed-transition', 'Transitioning out of crib — timing matters for sleep', 'safety', 'advisory',
   78, 104, 130,
   2, 'Moving from crib to toddler bed too early is one of the most common causes of sleep regression in the second year. Most sleep experts recommend keeping children in a crib until 3 years old unless there is a safety reason (climbing out consistently). The crib is a sleep boundary. Remove it too early and you spend months managing a child who is free to roam.', '* If climbing out: lower the mattress first, use a sleep sack to limit leg range, then transition if climbing continues
* Transition around age 3 when the child can understand and follow the boundary of staying in bed
* Involve the child in choosing their new bed to create buy in',
   'There is no developmental reason to rush this transition. A child still in a crib at 3 is fine.', 'If you have already transitioned too early and are dealing with nightly escapes, use a consistent return to bed protocol: minimal interaction, same words, same calm return every time.', 'AAP Sleep Guidelines; Mindell (2005), Sleeping Through the Night',
   NULL, FALSE, TRUE),
  ('safety-forward-facing-transition', 'Car seat: forward-facing transition — weight and height based', 'safety', 'advisory',
   104, 130, 156,
   2, 'When a child has outgrown the rear facing limits of their seat (by height or weight, not by age), they transition to a forward facing harness seat. This is still significantly safer than a booster. The forward facing harness should be used until the child outgrows it as well, usually around 40 to 65 lbs depending on the seat.', '* Check your seat''s rear facing limit: if your child''s head is within 1 inch of the top of the seat, they have outgrown it
* Move to a forward facing convertible seat with a 5 point harness, not a booster yet
* Ensure the harness is at or above shoulder level in forward facing mode',
   'There is no hurry to move to a booster. A forward facing harness is much safer than a booster at this age and weight range.', 'If your child is already in a booster before age 4 or before reaching 40 lbs, move them back to a harnessed seat if possible.', 'NHTSA (2024); AAP Car Seat Guideline; Insurance Institute for Highway Safety',
   NULL, FALSE, TRUE),
  ('safety-infant-cpr', 'Parent infant CPR training', 'safety', 'advisory',
   0, 0, 17,
   1, 'Infant CPR is one of the most important skills a new parent can have, and one of the least likely to be used. In the event of a choking incident or respiratory emergency, the minutes before emergency services arrive are critical. Parents who have received hands on CPR training respond more effectively and more calmly than those who have only watched a video. The training takes 2 hours and can be done before the baby arrives.', '* Take a hands on infant CPR and first aid class before or shortly after birth, hospital classes, Red Cross, or local fire stations often offer them
* Video only learning is better than nothing but significantly less effective than hands on practice
* Ensure any regular caregivers (grandparents, nanny) are also trained',
   'You don''t need to memorize every step. The muscle memory from hands on practice is what matters, it takes over in an emergency when memory fails.', 'It''s never too late to take this class. If you''re past 4 months and haven''t done it, schedule it this week.', 'American Red Cross, Infant CPR Guidelines; AAP Bright Futures; AHA Infant CPR Training Evidence',
   NULL, FALSE, TRUE),
  ('safety-poison-control', 'Poison control number saved — 1-800-222-1222 (US)', 'safety', 'advisory',
   0, 0, 52,
   2, 'Poisoning is one of the top causes of accidental injury in children under 5. Most poisoning calls to poison control involve household products (cleaning supplies, medications, vitamins, batteries) found by mobile toddlers. Having the number already saved means you are not searching for it while your child is in distress.', '* US Poison Control: 1 800 222 1222. Save it in your phone now.
* Ensure all medications (including vitamins) are in child resistant containers and stored out of reach
* Button batteries (in remotes, key fobs, musical cards) are the most dangerous household poisoning risk, they cause severe internal burns within 2 hours if ingested',
   'Most poison control calls end without emergency intervention. The specialists will tell you exactly what to do based on what was ingested and the quantity.', 'Save the number today if you haven''t. Check your home for accessible medications and batteries this week.', 'National Capital Poison Center; AAP Injury Prevention; Safe Kids Worldwide',
   NULL, FALSE, TRUE),
  ('safety-rear-facing-as-long-as-possible', 'Stay rear-facing as long as possible — not just to age 2', 'safety', 'advisory',
   0, 0, 104,
   2, 'The AAP and NHTSA recommend keeping children rear facing until they reach the maximum height or weight limit of their rear facing car seat, not just until age 2. Rear facing is significantly safer in frontal crashes (the most common type) because it distributes crash forces across the entire back, head, and neck. Turning forward facing too early exposes the neck and spine to forces they are not yet developed enough to handle safely.', '* Check the weight and height limit of your specific seat, not a generic age guideline
* Most convertible car seats support rear facing up to 40 to 50 lbs, many toddlers can stay rear facing until age 4
* Folded or crossed legs in a rear facing seat are safe, the legs are not a safety issue',
   'Folded legs are safe. Discomfort from a cramped position is not a reason to switch. Children who have always been rear facing rarely object to it.', 'If you have already turned your child forward facing, ensure the forward facing seat is correctly installed and the harness is properly fitted at the correct slot height.', 'NHTSA (2024); AAP Car Seat Safety Policy; Insurance Institute for Highway Safety',
   NULL, FALSE, TRUE),
  ('safety-room-sharing', 'Room-sharing without bed-sharing — AAP recommendation', 'safety', 'advisory',
   0, 0, 26,
   1, 'Room sharing (baby in your room, in their own sleep space) reduces SIDS risk by up to 50% compared to sleeping in a separate room. Bed sharing increases SIDS risk, particularly when the parent has consumed alcohol, medication, or is extremely fatigued. The AAP recommends room sharing for at least the first 6 months, ideally the first year. This is one of the most straightforward risk reduction measures available and costs nothing.', '* Keep the crib or bassinet in your room for the first 6 months
* If you''re tempted to bring the baby into your bed during a night feed: set up the sleep space to make transfer back easy, darkness, white noise, firm surface nearby
* After 6 months, transitioning to their own room is developmentally appropriate and safe',
   'Room sharing does not doom you to sleep disruption forever. The transition to their own room after 6 months is typically smooth.', 'If your baby is already in a separate room before 6 months and you choose to maintain that, discuss the risk tradeoff with your pediatrician. Some families find that room sharing is more disruptive to parental sleep, which creates its own risks. Individual circumstances vary.', 'AAP Safe Sleep Guidelines (2022); Carpenter et al. (2013), Room Sharing Evidence; Pediatrics (2022)',
   NULL, FALSE, TRUE),
  ('safety-safe-sleep-setup', 'Safe sleep setup — before baby arrives', 'safety', 'advisory',
   0, 0, 4,
   1, 'Approximately 3,500 infants die each year in the US from sleep related causes, SIDS, accidental suffocation, and entrapment. The vast majority are preventable with the right sleep environment. The time to set up a safe sleep space is before the baby arrives, not at 2am after a long delivery. This is the single most important safety preparation for a new parent.', '* Baby sleeps alone, on their back, on a firm, flat surface, in a crib, bassinet, or play yard that meets current safety standards
* Nothing in the sleep space: no pillows, no loose blankets, no bumpers, no positioners, no stuffed animals
* Room temperature should be comfortable for a lightly dressed adult, no need to bundle',
   'You don''t need an expensive crib. A firm, flat, appropriately sized sleep surface is the requirement. A $50 play yard with a proper mattress is safer than an expensive vintage crib with a soft mattress.', 'If your baby is already here and the sleep environment doesn''t meet these guidelines: change it tonight. This is not a gradual transition.', 'AAP Safe Sleep Guidelines (2022); Pediatrics, SIDS and Other Sleep Related Infant Deaths (2022 Update); Safe to Sleep Campaign',
   'getfamilyforce.com/playbook-sleep', FALSE, TRUE),
  ('safety-sunscreen-6months', 'Sunscreen from 6 months — SPF 30+ on exposed skin', 'safety', 'advisory',
   26, 26, 156,
   2, 'Baby skin is thinner and more permeable than adult skin and burns faster. Sunburn in infancy increases lifetime risk of melanoma. Under 6 months, the AAP recommends avoiding direct sun exposure and using shade and protective clothing rather than sunscreen, as infant skin absorbs chemicals more readily. From 6 months, SPF 30 or higher sunscreen should be applied to all exposed skin before sun exposure.', '* Apply SPF 30 or higher broad spectrum sunscreen 15 minutes before going outside
* Choose mineral sunscreens (zinc oxide or titanium dioxide) for babies, they sit on the skin rather than being absorbed
* Reapply every 2 hours and after water exposure',
   'Sunscreen is safe for babies from 6 months. The small amount of chemical absorption from mineral sunscreens poses no documented health risk and is far outweighed by the protection provided.', 'If your baby under 6 months needs to be in the sun: protective clothing, a hat, and shade are the primary tools.', 'AAP Sun Safety Guidelines (2023); Skin Cancer Foundation; FDA Sunscreen Safety',
   'getfamilyforce.com/playbook-screen-time', FALSE, TRUE),
  ('safety-swaddle-transition', 'Swaddle transition — stop when rolling signs appear', 'safety', 'advisory',
   12, 14, 17,
   1, 'A swaddled baby who rolls face down cannot push themselves back up or move their face away from the mattress. This is a suffocation risk. The AAP is unambiguous: stop swaddling the moment your baby shows any signs of rolling, attempting to roll, rocking side to side, or getting one shoulder off the mat during tummy time. Most babies show these signs between 2 and 4 months.', '* Watch for rolling signs during tummy time: rocking onto one shoulder, getting a knee under the body
* The day you see a rolling attempt: stop swaddling that night, cold turkey
* Transition options: a sleep sack (arms free), a wearable blanket, or nothing, all are safe. Some babies need a few rough nights to adjust.',
   'Sleep will get worse before it gets better when you drop the swaddle. This is temporary. The safety benefit is not worth compromising.', 'If your baby is already rolling and still being swaddled, stop tonight. This is not a gradual transition, it''s a safety call.', 'AAP Safe Sleep Guidelines (2022); SIDS and Other Sleep Related Infant Deaths: Evidence Base for 2016 Updated Recommendations (Pediatrics)',
   NULL, FALSE, TRUE),
  ('safety-water-supervision', 'Water safety — never leave unattended near water, any depth', 'safety', 'advisory',
   26, 52, 156,
   1, 'Drowning is the leading cause of accidental death for children ages 1–4. A child can drown in less than 2 inches of water. Bath tubs, buckets, toilets, garden ponds, and paddling pools are all hazards, not just pools and lakes. The rule is simple and absolute: within arm''s reach whenever near any water, any depth. No exceptions. Not for a phone call. Not to answer the door.', '* Arm''s reach rule: if you''re not touching them, you''re too far
* Empty any container of standing water after use: bath, paddling pool, buckets
* Pool fences with self closing, self latching gates are the standard, and they save lives',
   'Swimming lessons from 12 months onward reduce drowning risk, they are worth doing. But they do not replace supervision. A child who can swim can still drown.', 'Water safety supervision is a rule that doesn''t close. It remains essential until children are reliable, competent swimmers, usually not before age 6 or 7.', 'AAP Drowning Prevention Policy; CDC Child Drowning Statistics; American Red Cross Water Safety',
   NULL, FALSE, TRUE),
  ('screening-blood-lead', 'Blood lead level screen', 'screening', 'screening',
   26, 52, 65,
   2, 'Lead exposure has no safe level in children. Even low blood lead levels are associated with reduced IQ, attention difficulties, and behavioral problems. Lead exposure comes from old paint (homes built before 1978), contaminated soil, old plumbing, and some imported toys. The AAP recommends screening at 12 and 24 months for all children, with earlier screening if risk factors are present.', '* Ask your pediatrician about lead screening at the 12 month visit if it has not been offered
* If you live in an older home or have concerns about your water pipes, mention this explicitly
* The test is a simple blood draw or finger prick',
   'A result at or near the detection limit is not a crisis. The goal is identifying elevated levels early, when dietary and environmental interventions are most effective.', 'If your child has not been screened by 24 months and you live in an older home or high risk area, request a blood lead test at the next visit.', 'AAP Council on Environmental Health (2016); CDC Blood Lead Reference Value',
   'getfamilyforce.com/playbook-screen-time', FALSE, TRUE),
  ('screening-dental-first-visit', 'First dental visit — at first tooth, or by 12 months', 'screening', 'screening',
   17, 26, 52,
   1, 'The AAPD (American Academy of Pediatric Dentistry) recommends the first dental visit when the first tooth appears or by 12 months, whichever comes first. Baby teeth matter. Tooth decay in infants and toddlers is the most common chronic disease in children, 5x more prevalent than asthma. Early decay causes pain, affects eating, affects speech development, and predicts poor adult dental health. The first visit is as much about parent education as it is about the child''s teeth.', '* Schedule when the first tooth appears, don''t wait until 12 months if teeth arrive early
* Wipe teeth with a soft cloth or infant toothbrush from the first tooth
* No fluoride toothpaste until age 2 (a rice grain size amount from 6–24 months, pea size from 2+)
* Night bottles of milk or juice after teeth appear: a leading cause of early childhood tooth decay',
   'The first dental visit is brief and non invasive. It''s primarily about checking tooth eruption, discussing oral hygiene, and setting habits.', NULL, 'AAPD Guideline on Infant Oral Health (2022); AAP Oral Health Guidelines; AAPD Policy on Early Childhood Caries',
   'getfamilyforce.com/playbook-screen-time', FALSE, TRUE),
  ('screening-hearing-rescreen', 'Hearing re-screen — if any concern arises', 'screening', 'screening',
   0, 52, 156,
   2, 'Passing the newborn hearing screen does not guarantee lifetime normal hearing. Hearing loss can develop in the first years of life due to chronic ear infections (otitis media with effusion), genetic factors, or illness. Any parent concern about hearing should be taken seriously and acted upon promptly.', '* If you have any doubt about your child''s hearing at any age, ask for a referral to audiology
* Signs to watch for: not responding to their name, not startling to loud sounds, significant speech delay, frequently asking "what?" or turning up the TV volume
* Three or more ear infections in one year is a risk factor for hearing impact',
   'Children with temporary hearing loss from fluid in the middle ear (glue ear) often catch up fully once the fluid resolves. Persistent concerns warrant formal audiological evaluation regardless.', 'If you have a nagging feeling that your child''s hearing is not quite right, act on it. Audiological evaluations are non invasive and the cost of missing early hearing loss is high.', 'JCIH Position Statement (2019); AAP Hearing Screening Guidelines',
   'getfamilyforce.com/playbook-screen-time', FALSE, TRUE),
  ('screening-newborn-bilirubin', 'Newborn bilirubin (jaundice) check', 'screening', 'screening',
   0, 1, 2,
   1, 'Newborn jaundice, yellowing of skin and eyes, affects 60% of term newborns. Most cases are benign and resolve within 1–2 weeks. Severe untreated jaundice can cause brain damage (kernicterus). The standard is to check bilirubin levels before discharge and confirm follow up within 48 hours for babies discharged before 72 hours old.', '* Confirm bilirubin was checked before hospital discharge
* If discharged early (under 48 hours): ensure a follow up is scheduled within 48 hours of discharge
* Warning signs of severe jaundice: yellow color spreading to the belly or limbs, extreme sleepiness, difficulty feeding',
   'Mild jaundice visible only in the face and chest in the first week, with a baby who is feeding well and alert, is common and usually self resolving.', NULL, 'AAP Hyperbilirubinemia Management Guidelines (2022); Pediatrics, Newborn Bilirubin Screening',
   'getfamilyforce.com/playbook-screen-time', FALSE, TRUE),
  ('screening-newborn-blood-spot', 'Newborn metabolic / blood spot screen — hospital', 'screening', 'screening',
   0, 0, 1,
   1, 'The newborn blood spot screen (heel prick) tests for 30+ serious metabolic, hormonal, and genetic conditions, including PKU, congenital hypothyroidism, cystic fibrosis, and sickle cell disease. Most of these conditions are treatable when caught early and devastating when missed. This is one of the highest value medical interventions in pediatrics.', '* The test is done in the hospital, usually 24–48 hours after birth
* Results come back within 1–2 weeks, ask your pediatrician if you haven''t heard back
* If any results are flagged: follow up immediately and ask for a clear explanation of what''s being tested',
   'Most abnormal initial results are false positives that resolve on repeat testing.', NULL, 'AAP Newborn Screening Policy; March of Dimes Newborn Screening Guidelines',
   'getfamilyforce.com/playbook-screen-time', FALSE, TRUE),
  ('screening-newborn-hearing', 'Newborn hearing screen — before hospital discharge', 'screening', 'screening',
   0, 0, 1,
   1, '1–3 per 1,000 babies are born with permanent hearing loss. Early detection, before 3 months, and early intervention, before 6 months, produces dramatically better language outcomes than detection at 12 or 18 months. The screen is painless, takes 10 minutes, and is done in the hospital.', '* Confirm with the nursing staff that the hearing screen has been scheduled before discharge
* If your baby doesn''t pass: a refer result does not mean hearing loss, it means another test is needed. Follow up within one month.',
   'A "refer" result at the newborn screen is common and usually resolves with a repeat test. It is not a diagnosis.', NULL, 'JCIH Year 2019 Position Statement; AAP Universal Newborn Hearing Screening Policy',
   'getfamilyforce.com/playbook-screen-time', FALSE, TRUE),
  ('screening-vision-12months', 'Vision screening — 12-month visit', 'screening', 'screening',
   52, 52, 65,
   2, 'Early identification of vision problems (amblyopia, strabismus, refractive errors) is critical because the visual system is still developing through age 7 to 8. Problems identified and treated before age 3 have significantly better outcomes than those caught at school entry. The 12 month visit includes a basic vision assessment.', '* At the 12 month visit, ensure a vision check is included, ask if it was not offered
* Note any eye turning, excessive squinting, or asymmetry in how the eyes move
* If there is a family history of eye conditions, mention it explicitly',
   'Eye crossing that resolved in the first few months of life is normal. Persistent or new eye turning after 4 months is what warrants attention.', 'If vision screening was not done at 12 months, ask for it at the next visit. Alternatively, request a referral to a pediatric ophthalmologist if you have any concerns.', 'AAP Vision Screening Policy (2016); AAPOS Guidelines',
   'getfamilyforce.com/playbook-screen-time', FALSE, TRUE),
  ('screening-visit-12months', '12-month well-child visit', 'screening', 'screening',
   52, 52, 54,
   1, 'The 12 month visit is one of the most important in the first year. It assesses walking, first words, pointing, social engagement, and the transition to whole cow''s milk. Vaccines: MMR, varicella, hepatitis A (dose 1), PCV booster (dose 4), Hib (dose 4).', '* Track words before the visit: how many specific, consistent words does your child have?
* Note pointing behavior, pointing to share interest (declarative) is key
* Transition to whole cow''s milk discussion',
   NULL, NULL, 'AAP Periodicity Schedule 2024; CDC 12 Month Milestones',
   'getfamilyforce.com/playbook-screen-time', FALSE, TRUE),
  ('screening-visit-15months', '15-month well-child visit', 'screening', 'screening',
   65, 65, 67,
   1, 'The 15 month visit assesses walking, word count (target: 10+ words), pointing, and social engagement. It''s a critical checkpoint for early identification of language delay and motor delay. Vaccines: DTaP (dose 4), Hib (dose 4 if needed), PCV (dose 4), influenza (annual), hepatitis A (dose 2).', '* Count your child''s words before the visit
* Note whether they''re walking independently (expected by 15 months per CDC 2022 guidance)
* Mention any concerns about language, behavior, or social engagement',
   NULL, NULL, 'AAP Periodicity Schedule 2024; CDC 15 Month Milestones (2022 update)',
   'getfamilyforce.com/playbook-screen-time', FALSE, TRUE),
  ('screening-visit-18months-autism', '18-month well-child visit + M-CHAT autism screen', 'screening', 'screening',
   78, 78, 80,
   1, 'The 18 month visit is the first formal autism screening using the M CHAT R/F. It also assesses vocabulary (target: 10–20 words), two word combinations emerging, walking, and behavior. The M CHAT is not a diagnosis, it identifies children who need further evaluation. Early identification before 24 months produces substantially better outcomes. Vaccines: hepatitis A (dose 2 if not given), influenza.', '* Complete the M CHAT questionnaire honestly, don''t answer what you wish were true
* Prepare observations: name response, pointing, vocabulary count, eye contact, social engagement
* If the M CHAT indicates follow up: take it seriously and move quickly. Earlier evaluation = better outcomes.',
   NULL, NULL, 'AAP Autism Screening Policy; Robins et al. (2014), M CHAT R/F Validation; CDC Autism Screening Guidelines',
   'getfamilyforce.com/playbook-screen-time', FALSE, TRUE),
  ('screening-visit-24months-autism', '24-month well-child visit + autism screen', 'screening', 'screening',
   104, 104, 106,
   1, 'The 24 month visit includes a second autism screen (M CHAT R/F or equivalent). It also assesses vocabulary (target: 50+ words), two word combinations, social play, and the tantrum pattern. This is the most comprehensive developmental assessment in the first two years and often the first time significant language delay becomes clearly visible.', '* Complete the developmental questionnaire accurately
* Be direct about concerns, this is not the time to minimize
* If there are language or social concerns: ask for a speech evaluation referral today',
   NULL, NULL, 'AAP Autism Screening Policy; CDC 24 Month Milestones; M CHAT R/F',
   'getfamilyforce.com/playbook-screen-time', FALSE, TRUE),
  ('screening-visit-2months', '2-month well-child visit', 'screening', 'screening',
   8, 8, 10,
   1, 'The 2 month visit is a developmental milestone check and the start of the vaccination schedule. Vaccines given at 2 months: DTaP, Hib, PCV15, rotavirus, polio, hepatitis B (dose 2). The developmental assessment covers social smile, cooing, head control, and visual tracking.', '* Schedule on time, vaccines are timed to the immune system''s development
* Expect fussiness and mild fever for 24–48 hours after vaccines: normal
* Ask about tummy time progress and what to expect before the 4 month visit',
   NULL, NULL, 'AAP Periodicity Schedule 2024; CDC Immunization Schedule 2024',
   'getfamilyforce.com/playbook-screen-time', FALSE, TRUE),
  ('screening-visit-30months', '30-month well-child visit — developmental screen', 'screening', 'screening',
   130, 130, 132,
   1, 'The 30 month visit was added to the AAP schedule specifically for developmental surveillance. It assesses 3 word sentences, cooperative play, comprehension, and behavior. The gap between 24 months and 36 months is long enough that language delays can become significantly entrenched, the 30 month visit catches issues while intervention is still highly effective.', '* Note sentence length: most 30 month olds use 3 word sentences regularly
* Note social behavior: does your child play with, not just alongside, other children?
* Bring any concerns about behavior, tantrums, sleep, or language',
   NULL, NULL, 'AAP Periodicity Schedule 2024 (30 month addition); CDC 30 Month Milestones',
   'getfamilyforce.com/playbook-screen-time', FALSE, TRUE),
  ('screening-visit-36months', '36-month well-child visit', 'screening', 'screening',
   156, 156, 158,
   1, 'The 36 month visit marks the end of the most intensive developmental surveillance period. It assesses full sentences (4+ words), imaginative play, social skills, potty training readiness/progress, and school readiness. It''s also a preview of the annual well child schedule that begins at age 3. Vaccines: DTaP (dose 5), MMR (dose 2), varicella (dose 2), IPV (dose 4), influenza.', '* Discuss potty training if not already completed, the window is open
* Note whether your child''s speech is understood by unfamiliar adults (~75% understandable is the target)
* Ask about preschool readiness if relevant',
   NULL, NULL, 'AAP Periodicity Schedule 2024; CDC 36 Month Milestones',
   'getfamilyforce.com/playbook-screen-time', FALSE, TRUE),
  ('screening-visit-3to5-days', 'First pediatrician visit — 3 to 5 days', 'screening', 'screening',
   0, 1, 1,
   1, 'The 3–5 day visit is primarily about weight. Newborns lose up to 10% of their birth weight in the first days and should be back to birth weight by 10–14 days. This visit confirms the baby is regaining weight, feeding is working, jaundice is resolving, and the family is coping. It''s a safety net, not a social call.', '* Schedule before discharge from the hospital
* Track feeding: number of feeds per day, duration, wet and dirty diapers (a good proxy for intake)
* Write down your questions, the first week is chaotic, and you will forget them',
   NULL, NULL, 'AAP Periodicity Schedule 2024; AAP Newborn Discharge Guidelines',
   'getfamilyforce.com/playbook-screen-time', FALSE, TRUE),
  ('screening-visit-4months', '4-month well-child visit', 'screening', 'screening',
   17, 17, 19,
   1, 'The 4 month visit covers head control, rolling readiness, responsive feeding, and iron supplementation for breastfed babies. Vaccines: DTaP (dose 2), Hib (dose 2), PCV (dose 2), rotavirus (dose 2), polio (dose 2). This is also when the 4 month sleep regression is typically discussed.', '* Ask specifically about iron supplementation if breastfeeding
* Discuss the 4 month sleep regression and what''s coming
* Ask about solid food readiness signs to watch for',
   NULL, NULL, 'AAP Periodicity Schedule 2024; AAP Iron Supplementation Guidance',
   'getfamilyforce.com/playbook-screen-time', FALSE, TRUE),
  ('screening-visit-6months', '6-month well-child visit', 'screening', 'screening',
   26, 26, 28,
   1, 'The 6 month visit assesses sitting with support, babbling, hand to hand transfer, and object permanence emerging. It''s also the green light for solid food introduction and the first flu vaccine. Vaccines: DTaP (dose 3), Hib (dose 3), PCV (dose 3), polio (dose 3), influenza (annual), hepatitis B (dose 3).', '* Bring the solid food questions, this is the right time to ask about puree progression and allergen introduction
* Ask about the peanut introduction protocol for your baby specifically (eczema history, family allergy history)',
   NULL, NULL, 'AAP Periodicity Schedule 2024; AAP Early Allergen Introduction Guidance',
   'getfamilyforce.com/playbook-screen-time', FALSE, TRUE),
  ('screening-visit-9months', '9-month well-child visit — developmental surveillance', 'screening', 'screening',
   39, 39, 41,
   1, 'The 9 month visit is the first formal developmental screening using a standardized tool (ASQ or similar). It assesses sitting independently, pulling to stand, babbling, responding to name, and early social engagement. No vaccines at this visit typically. This visit is where pointing and joint attention first become clinically observable.', '* Complete any pre visit developmental questionnaire the practice sends (ASQ 3 is common)
* Bring specific behavioral observations: does the baby respond to their name? Point at things?',
   NULL, NULL, 'AAP Periodicity Schedule 2024; ASQ 3 Developmental Screening',
   'getfamilyforce.com/playbook-screen-time', FALSE, TRUE),
  ('social-bedtime-routine-security', 'Consistent bedtime routine — builds emotional security', 'social', 'advisory',
   12, 17, 52,
   2, 'A predictable bedtime routine (bath, book, song, bed, always in the same order) reduces cortisol levels in children before sleep, shortens the time it takes to fall asleep, and improves sleep quality. Research by Mindell et al. found that a consistent 3 to 4 step bedtime routine produced measurable sleep improvements within one week. The routine signals safety: what happens next is predictable, and predictability is the foundation of emotional security.', '* Choose 3 to 4 steps that work for your family and do them in the same order every night
* Keep the routine under 30 minutes to prevent overtiredness
* Both parents should be able to execute the same routine so there is no dependency on one person',
   'The specific activities matter less than the consistency. "Bath, book, bed" is as effective as any elaborate version.', 'It is never too late to establish a bedtime routine. Even starting at 12 months produces measurable improvement within days to weeks.', 'Mindell et al. (2009), Bedtime Routine Study; AAP Sleep Guidelines',
   NULL, FALSE, TRUE),
  ('social-caregiver-transition', 'Caregiver/daycare transition — how to make it easier', 'social', 'advisory',
   4, 26, 52,
   2, 'Transitions to new caregivers or daycare are among the most stressful events of the first two years for both parent and child. How the transition is handled significantly affects the child''s adjustment. A gradual, supported transition produces faster settling and better long term outcomes than an abrupt start.', '* Start with short periods at the new setting: 1 to 2 hours, then build up over 1 to 2 weeks
* Bring a comfort object from home that smells like a parent
* Establish a consistent goodbye ritual: same words, same hug, same quick exit',
   'Crying at drop off is not evidence of trauma. Most children settle within minutes after the parent leaves. The transition is harder for parents than it is for children in most cases.', 'If your child has been in daycare for several months and still does not settle within 10 minutes of drop off, talk to both the caregivers and your pediatrician.', 'Bowlby (1969); NICHD Study of Early Child Care (2003)',
   NULL, FALSE, TRUE),
  ('social-consistent-discipline', 'Consistent, calm discipline approach', 'social', 'advisory',
   52, 65, 156,
   2, 'Consistency is the single most important variable in discipline effectiveness. The approach itself (time outs, natural consequences, redirection, positive reinforcement) matters less than whether it is applied consistently. A child who receives the same response to a behavior every time learns quickly. A child who receives unpredictable responses continues to test because unpredictability is confusing.', '* Agree on the approach with your co parent and apply it the same way every time
* State the limit clearly and calmly before enforcing it: "if you throw the food again, we will leave the table"
* Follow through. Every single time. Inconsistency teaches that limits are negotiable.',
   'The child will test the limit anyway. Consistent enforcement does not feel like it is working in the first week. It is. The behavior data shows improvement over 2 to 4 weeks of consistent response.', 'If discipline is chaotic or inconsistent in your household, starting a consistent approach at any age produces measurable improvement. The earlier the better, but it is always worth doing.', 'Patterson (1982), Coercive Family Process; Baumrind (1971), Authoritative Parenting; AAP Discipline Guidance',
   NULL, FALSE, TRUE),
  ('social-cooperative-play', 'Cooperative play begins — plays WITH other children', 'social', 'advisory',
   104, 117, 156,
   2, 'Cooperative play (taking turns, following shared rules, working toward a common goal in play) emerges around 2.5 to 3 years. It requires theory of mind (understanding that others have their own thoughts and intentions) and enough self regulation to take turns. It is a significant social milestone and a predictor of school readiness.', '* Arrange regular play with the same children so bonds and familiarity develop
* Simple structured games (rolling a ball back and forth) scaffold the turn taking concept
* Narrate: "now it is her turn. Now it is your turn."',
   'Conflict during early cooperative play is completely normal. Children are learning to negotiate for the first time. The conflict is the lesson.', 'If your 3 year old has no interest in playing with other children at all (not just near them), mention it at the 36 month visit.', 'Parten (1932); Vygotsky (1978), Zone of Proximal Development; CDC',
   NULL, FALSE, TRUE),
  ('social-empathy-emerging', 'Empathy emerging — shows concern when others are upset', 'social', 'advisory',
   78, 104, 130,
   2, 'Around 18 to 24 months, children begin to show genuine concern for others who are distressed: offering a toy to a crying friend, patting a parent who looks sad. This is early empathy, and it is the foundation of prosocial behavior. It emerges from a consistent history of having their own emotions recognized and responded to.', '* Acknowledge and respond to your child''s emotions consistently
* Label the emotions of people in books and real life: "the baby is crying because she is sad"
* Model empathic behavior toward others, children learn far more from watching than from being told',
   'Early empathy is inconsistent. A child may comfort their parent one day and ignore a crying friend the next. The behavior becoming more consistent over time is what matters.', 'Complete absence of any prosocial concern for others by 30 months is worth noting in the context of other social observations.', 'Zahn Waxler et al. (1992), Empathy Development Research; Hoffman (2000)',
   NULL, FALSE, TRUE),
  ('social-father-partner-bonding', 'Father/partner bonding — equally important from birth', 'social', 'advisory',
   0, 0, 26,
   2, 'Research consistently shows that active father and co parent involvement from birth predicts better cognitive, social, and emotional outcomes for children. Fathers who are involved from birth develop stronger attachment, more confidence as parents, and children who benefit from two distinct interaction styles. Rougher, more unpredictable play (more typical of fathers) builds the child''s stress regulation and risk tolerance in a different way than nurturing maternal interactions.', '* The non birthing parent should handle at least one night feed per night from the beginning
* Skin to skin contact for co parents is as beneficial for them as for the birth parent
* Both parents should have regular independent time with the baby without the other present',
   'A partner who feels less confident than the primary caregiver is normal. Confidence comes from repetition. The answer is more solo time with the baby, not less.', 'If one parent has taken on almost all caregiving through the first 6 months, it is not too late to rebalance. Co parents who become more involved at 6 months still form strong attachments.', 'Lamb (1977), Paternal Involvement; Paquette (2004), Activation Relationship Theory; AAP',
   NULL, FALSE, TRUE),
  ('social-gratitude-empathy-practice', 'Practice gratitude and empathy at the table', 'social', 'advisory',
   104, 117, 195,
   3, 'Gratitude and empathy are teachable through repeated practice in low stakes, everyday contexts. Mealtime provides a consistent, captive setting for this. Research by Robert Emmons and others shows that children in families with regular gratitude practices show measurably higher wellbeing, prosocial behavior, and relationship quality by age 10. The mechanism is habit formation through repetition in early childhood.', '* Introduce a simple mealtime ritual: one thing each person is grateful for today
* Name emotions at the table: "you look frustrated, what happened today?"
* Express genuine appreciation for the meal and for each other in simple terms',
   'Young children will give arbitrary or silly answers ("I am grateful for dinosaurs"). This is exactly right. The habit of pausing to notice good things is more important than the content of the answer.', 'This practice is most powerful when started early but remains valuable at any age. Starting now is not too late.', 'Emmons and McCullough (2003), Gratitude and Well Being Research; Eisenberg et al. (2006), Empathy in Childhood',
   NULL, FALSE, TRUE),
  ('social-imaginary-friends', 'Imaginary friends — normal and healthy at this stage', 'social', 'advisory',
   130, 156, 195,
   3, 'Imaginary companions are a common and healthy feature of social development in 25 to 65% of children between ages 2.5 and 7. Research by Marjorie Taylor shows that children with imaginary friends are not lonely or confused about reality, they are often more socially skilled, better at perspective taking, and more creative than peers without imaginary friends. The imaginary friend is a safe space to practice social interaction.', '* Engage with the imaginary friend playfully: "should we set a place at the table for them?"
* Do not dismiss or ridicule the imaginary companion
* Take it as a positive sign: it is evidence of active imagination, strong narrative capacity, and social rehearsal',
   'An imaginary friend who the child knows is not real is healthy. The concern (which is rare) would be a child who cannot distinguish their imaginary friend from reality or who is severely distressed when others do not acknowledge them.', 'There is no intervention needed for imaginary friends. Simply support and engage with the play.', 'Taylor (1999), Imaginary Companions and the Children Who Create Them; CDC; AAP',
   NULL, FALSE, TRUE),
  ('social-independence-me-do-it', 'The "me do it" phase — support independence safely', 'social', 'advisory',
   78, 91, 130,
   2, 'The fierce insistence on doing things independently ("me do it!") that peaks around 18 to 24 months is not defiance, it is the emergence of autonomy, which is a healthy and necessary developmental drive. How parents respond to this phase shapes the child''s sense of competence and their relationship with effort. Allowing safe independent attempts, even slow or messy ones, builds confidence and persistence.', '* Build extra time into routines so they can try things themselves: putting on shoes, carrying their cup
* Offer limited choices to support autonomy: "do you want the red shirt or the blue one?"
* When something is too dangerous: "you can do the zipper, I need to do the buckle"',
   'Everything taking twice as long is temporary. The investment in allowing independent attempts pays off in a more capable and confident 3 and 4 year old.', 'If your 2 year old shows no interest in doing anything for themselves and is passive about all tasks, it is worth discussing with your pediatrician.', 'Erikson (1950), Autonomy vs Shame; Deci and Ryan, Self Determination Theory; AAP',
   NULL, FALSE, TRUE),
  ('social-joint-attention', 'Joint attention — follows your point, shares interest', 'social', 'clinical',
   26, 34, 47,
   1, 'Joint attention, pointing at something to share interest with you, then looking back to see your reaction, is one of the most important developmental milestones in the first year. It emerges around 9 months and is the foundation of language, social cognition, and learning. Babies who point more at 9–12 months have larger vocabularies at 18 months. Absent pointing by 12 months is the single strongest behavioral predictor of autism spectrum disorder.', '* Point at things yourself, constantly: "Look, a dog." Then look at your baby to see if they follow your point
* When your baby points, respond immediately: name what they''re pointing at, share the moment
* Engage with whatever captures their attention, joint attention is about shared interest, not directed instruction',
   'There are two kinds of pointing: imperative (pointing to get something) and declarative (pointing to share). Declarative pointing, "look at that cool thing!", is the milestone that matters most and is the autism screening signal. Imperative pointing develops slightly earlier.', NULL, 'Baron Cohen et al., Pointing as ASD Predictor; Carpenter et al. (1998), Joint Attention Research; CDC Developmental Milestones; AAP M CHAT R/F Screening',
   NULL, FALSE, TRUE),
  ('social-label-big-feelings', 'Label big feelings out loud — names the emotion', 'social', 'advisory',
   52, 65, 104,
   2, 'Naming emotions is one of the most important things a parent can do during the toddler years. When you say "you are so frustrated right now" during a meltdown, you are not just describing the situation, you are providing a cognitive framework that the child''s developing prefrontal cortex will use to process that emotion. Research by Matthew Lieberman showed that naming feelings literally reduces the intensity of the emotional response in the brain.', '* Name the emotion before you redirect or problem solve: "I can see you are really angry. You wanted that toy."
* Use precise words: angry, frustrated, disappointed, excited, nervous, not just "upset"
* Label your own feelings too: "I am feeling impatient right now"',
   'You do not need the child to repeat the word back to you for this to work. The effect is neurological, not linguistic. You are rewiring their brain whether they acknowledge it or not.', 'This practice is valuable at any age. Starting now is never too late.', 'Lieberman et al. (2011); Gottman (1997); Zero to Three',
   NULL, FALSE, TRUE),
  ('social-parallel-play', 'Parallel play — plays alongside other children', 'social', 'advisory',
   52, 65, 104,
   2, 'Parallel play (playing near other children but not with them, doing similar activities independently) is the normal form of social play from age 1 to 3. It is not antisocial, it is the developmental precursor to cooperative play. Children in parallel play observe each other closely and learn through watching.', '* Arrange playdates or park time with other children of similar age
* Do not force interaction, let proximity do the work
* Narrate what other children are doing: "Oliver is building a tower. What are you building?"',
   'A toddler who does not play with other children but plays near them is exactly on track. Cooperative play typically doesn''t emerge reliably until after age 3.', 'If your 3 year old completely avoids any proximity to other children or shows no interest in watching them, mention it at the 36 month visit.', 'Parten (1932), Social Play Stages; AAP',
   NULL, FALSE, TRUE),
  ('social-parent-depression-screening', 'Parent mental health — screen for postpartum depression', 'social', 'screening',
   0, 6, 26,
   1, 'Postpartum depression affects 1 in 5 mothers and 1 in 10 fathers. It is one of the most common and most under treated complications of childbirth. Untreated postpartum depression affects not just the parent but the child, studies consistently show that parental depression in the first year is associated with disruptions in attachment, language development, and emotional regulation in children. This is a screening window, not a judgment. The question is not whether you''re a good parent, it''s whether your brain chemistry is working against you.', '* The Edinburgh Postnatal Depression Scale (EPDS) is the standard screening tool, your OB or pediatrician should offer it at the 6 week visit
* If you''re not screened: ask. Specifically: "Can I do the postpartum depression screen today?"
* Partners should also screen, paternal postpartum depression is real, underdiagnosed, and treatable',
   'Baby blues (tearfulness, emotional volatility in the first 2 weeks) are normal hormonal adjustment and resolve on their own. Postpartum depression is distinct: it persists beyond 2 weeks, and often involves more than sadness, anxiety, numbness, and disconnection are common presentations.', 'Postpartum depression can emerge up to 12 months after birth. If you are experiencing persistent low mood, anxiety, numbness, or difficulty connecting with your baby at any point in the first year, raise it with your OB or family doctor.', 'Edinburgh Postnatal Depression Scale (Cox et al., 1987); AAP Postpartum Depression Screening Guidelines; Paulson & Bazemore (2010), Paternal Postpartum Depression',
   'getfamilyforce.com/playbook-screen-time', FALSE, TRUE),
  ('social-parent-self-care', 'Parent self-care — oxygen mask principle', 'social', 'advisory',
   0, 0, 52,
   2, 'A dysregulated parent cannot regulate a dysregulated child. A depleted parent cannot provide the consistent warmth and responsiveness that secure attachment requires. Parent wellbeing is directly connected to child wellbeing. This is not a self indulgent message. It is a developmental one.', '* Identify the minimum self care that keeps you functional: sleep, food, one hour of quiet, movement
* Ask for help before you are in crisis, not after
* Accept offers of help. Declining help does not make you a better parent.',
   'Self care does not mean vacations and massages. It means meeting your basic needs consistently so you can show up for your child.', 'If you are consistently running on empty, this is worth raising at your own doctor''s appointment, not just the baby''s.', 'Harvard Center on the Developing Child, Parent Wellbeing and Child Development; AAP Postpartum Care Guidelines',
   NULL, FALSE, TRUE),
  ('social-peek-a-boo', 'Peek-a-boo play — teaches object permanence and trust', 'social', 'advisory',
   17, 26, 43,
   2, 'Peek a boo is not just entertainment. It teaches object permanence (you disappear and reappear, you still exist), trust (you always come back), and the structure of social turn taking. It is also one of the earliest games where the baby learns to anticipate and laugh in expectation, which is a cognitive skill.', '* Use your hands, a cloth, a corner, any method of disappearing and reappearing
* Build anticipation: slow down before the reveal to create the "peek a boo" moment
* Let the baby initiate as they get older',
   'They will want to play the exact same version of the same game many times in a row. This is them cementing the concept. Repetition is the point.', 'This is an opportunity, not a mandate. If you haven''t done it, start now. It remains valuable through 18 months.', 'Bruner and Sherwood (1976), Peek a Boo and Shared Attention; AAP',
   NULL, FALSE, TRUE),
  ('social-peer-friendships', 'Peer friendship formation begins', 'social', 'advisory',
   130, 156, 195,
   2, 'True peer friendships (consistent preference for a specific other child, seeking them out, showing joy at reunion) begin to emerge around age 3. They are different from general sociability. Peer friendships are important for language development, theory of mind, conflict resolution skills, and emotional wellbeing.', '* Facilitate regular time with the same small group of children
* Help your child learn to enter play: "you could ask if you can play too"
* Take their social preferences seriously, if they keep talking about one child, facilitate that friendship',
   'Not all children form close friendships at age 3. Some are more comfortable in small groups or one on one. The goal is social engagement in some form, not a specific friendship structure.', 'If your 4 year old has no interest in other children and avoids all social interaction, discuss it with your pediatrician.', 'Dunn (1993), Young Children''s Close Friendships; CDC',
   NULL, FALSE, TRUE),
  ('social-primary-attachment', 'Primary attachment formation — the first 6 months', 'social', 'advisory',
   0, 0, 26,
   1, 'Attachment theory, developed by John Bowlby and extended by Mary Ainsworth, is one of the most robust bodies of research in developmental psychology. Secure attachment in the first 6 months predicts better emotional regulation, more resilient stress responses, stronger social skills, and even better academic outcomes through childhood. Secure attachment is built not through any single action but through the cumulative experience of a caregiver who is consistently present, responsive, and warm. You cannot spoil a baby.', '* Respond to cries, consistently and promptly. Research is unambiguous that responsive caregiving builds secure attachment. You cannot spoil an infant.
* Be present during waking hours: face to face time, physical closeness, eye contact
* Regulate yourself: a calm parent creates a calm baby. The nervous system is contagious.',
   'Attachment is built over months, not moments. One bad day, one missed cue, one necessary absence doesn''t break the bond. Consistent patterns matter. Single events don''t.', 'Attachment continues to develop beyond 6 months, this window represents the most critical foundation period, but the relationship continues to be shaped throughout childhood. If early months were difficult (illness, postpartum depression, NICU), focus on building consistency now.', 'Bowlby, J., Attachment and Loss; Ainsworth et al. (1978), Patterns of Attachment; Harvard Center on the Developing Child; van den Boom (1994), Attachment Intervention Research',
   NULL, FALSE, TRUE),
  ('social-respond-to-smile', 'Respond to your baby''s smile — the return volley', 'social', 'clinical',
   4, 6, 13,
   1, 'When your baby smiles at you, your response is the milestone, not just their smile. The serve and return social exchange is what wires the brain for emotional communication. A baby whose smiles are consistently met with warmth and engagement learns that the world is responsive. A baby whose signals go unnoticed learns the opposite. This is the emotional equivalent of the language serve and return interaction.', '* When your baby smiles: smile back, talk to them, lean in
* Put everything else down during face to face waking time in the first months, these minutes matter disproportionately
* If you''re struggling to engage (postpartum depression, exhaustion, stress), ask for help. The pattern matters, not perfection.',
   'You don''t need to be fully present every second. The research is about consistent patterns over weeks and months, not every single interaction.', 'Attachment and emotional responsiveness matter throughout childhood. If early months were difficult, building a warm, responsive pattern now still produces meaningful positive outcomes.', 'Tronick et al., Still Face Paradigm Research; Harvard Center on the Developing Child, Serve and Return',
   NULL, FALSE, TRUE),
  ('social-self-regulation', 'Self-regulation strategies — co-regulation first', 'social', 'advisory',
   78, 91, 156,
   2, 'Self regulation, the ability to manage emotions and behavior, does not develop in isolation. It develops through co regulation first: a calm adult repeatedly helping a dysregulated child return to baseline. Every time a parent stays calm during a meltdown, they are literally modeling the neural pathway the child needs to build. Research by Stuart Shanker shows that children who experience consistent co regulation develop significantly better self regulation by age 5.', '* Stay calm during meltdowns. Your nervous system is the regulator.
* Use physical co regulation: hold them, sit with them, speak slowly and quietly
* After they calm, name what happened: "that was so hard. You got really upset. And then you calmed down."',
   'You will not always stay calm. Rupture followed by repair is normal and also teaches resilience. What matters is the pattern, not the perfection.', 'This window is open throughout childhood. Consistent co regulation practice at any age produces measurable improvements in self regulation.', 'Shanker (2016), Self Reg; Siegel and Bryson (2011), The Whole Brain Child; Schore (1994)',
   NULL, FALSE, TRUE),
  ('social-separation-anxiety', 'Separation anxiety — normal and how to handle it', 'social', 'advisory',
   26, 34, 65,
   2, 'Separation anxiety typically peaks between 9 and 18 months. It reflects the child''s understanding that a parent exists and can leave (object permanence applied to people) combined with the inability to yet trust that the parent will come back. It is one of the most common sources of parenting stress in the first two years and also one of the most predictable.', '* Always say goodbye, do not sneak out. Sneaking out increases anxiety long term.
* Keep goodbyes brief and confident. Your tone communicates safety.
* Practice short separations so the child learns the pattern: you leave, you always come back.',
   'The intensity of the goodbye cry is not an indicator of how the child feels two minutes after you leave. Many children stop crying almost immediately. Daycare cameras (where available) will often show this.', 'Severe separation anxiety that does not improve at all by age 3 is worth discussing with your pediatrician. Manageable separation distress throughout the toddler years is normal.', 'Bowlby (1969); Ainsworth (1967); AAP',
   NULL, FALSE, TRUE),
  ('social-serve-return-loop', 'Serve and return emotional loop — reading cues and responding', 'social', 'advisory',
   0, 4, 52,
   2, 'Serve and return is the mechanism through which secure attachment is built moment to moment. A baby "serves" (looks, reaches, vocalizes) and the parent "returns" (responds with warmth, attention, and engagement). This cycle, repeated thousands of times, builds the neural pathways for emotional regulation, stress response, and social intelligence. The absence of consistent returns is one of the most documented early risk factors for developmental difficulties.', '* Notice the serve: a look, a reach, a sound, a gesture is an invitation to connect
* Return the serve: make eye contact, respond verbally, lean in
* Do not worry about perfection, the pattern over time matters more than any single exchange',
   'You will miss many serves. Every parent does. The research shows it is the overall pattern and consistency that matters, not the hit rate.', 'This practice is valuable throughout childhood. If you are starting later, start now. The brain retains plasticity well beyond infancy.', 'Harvard Center on the Developing Child; Tronick (2007); Schore (1994)',
   NULL, FALSE, TRUE),
  ('social-sharing-not-before-3', 'Sharing — don''t force before age 3 (normal development)', 'social', 'advisory',
   104, 130, 156,
   3, 'True sharing requires theory of mind (understanding that another person wants something you have) and impulse control sufficient to override the desire to keep it. Neither capacity is reliably developed before age 3. Forcing sharing before these capacities are in place does not teach sharing, it teaches that adults take things away arbitrarily. Researchers like Dacher Keltner and Kristine Onishi have studied this extensively and the findings are consistent: developmental readiness matters.', '* From ages 1 to 3: use turn taking instead of forced sharing. "When you are done, Oliver will have a turn."
* Validate ownership: "that is your truck. You decide when you are done."
* Model sharing generously in your own life and narrate it',
   'Toddlers who refuse to share are not developing into selfish adults. They are behaving in a developmentally appropriate way for their age and brain development stage.', 'If your 3 to 4 year old is still completely unable to take turns or wait for a desired toy with any support, it is worth discussing at the next visit.', 'Brownell et al. (2009), Spontaneous Sharing in Toddlers; AAP; Keltner (2009)',
   NULL, FALSE, TRUE),
  ('social-skin-to-skin', 'Skin-to-skin bonding — first hours matter', 'social', 'advisory',
   0, 0, 4,
   1, 'Skin to skin contact immediately after birth, baby placed on the parent''s bare chest, triggers hormonal responses in both parent and child that are foundational to bonding and breastfeeding. Oxytocin, sometimes called the bonding hormone, is released in both. Babies in skin to skin contact have more stable heart rates, better temperature regulation, and better breastfeeding outcomes. This matters for both the birth parent and their partner.', '* Request immediate skin to skin contact in your birth plan, it''s standard practice in most hospitals, but stating it explicitly increases the likelihood it happens
* Skin to skin can continue at home, it''s not just for the delivery room
* Partners benefit too: the hormonal response is not exclusive to the birthing parent',
   'If skin to skin wasn''t possible at birth, medical complications, C section, NICU stay, it doesn''t define the relationship. Bonding happens over time through consistent responsive caregiving. The first hours are important; they are not irreplaceable.', 'If the initial hours passed without skin to skin, continue with as much physical closeness as possible in the first weeks. Baby wearing, co sleeping safely, and responsive feeding all contribute to the same bonding outcomes over time.', 'AAP Breastfeeding Policy; Moore et al. (2016), Cochrane Review on Skin to Skin Care; ACOG Early Skin to Skin Guidelines',
   NULL, FALSE, TRUE),
  ('social-social-smile-appears', 'Social smile appears — first intentional social act', 'social', 'clinical',
   4, 6, 12,
   1, 'The social smile, a smile in direct response to your face and voice, not gas, typically appears around 6 weeks. It''s the first sign that your baby is engaging with the social world intentionally. Absent social smiling by 3 months is a clinical red flag and one of the early screening indicators for autism spectrum disorder. The smile is also the beginning of the serve and return emotional exchange that drives language and attachment development.', '* Get close, babies can only focus clearly at 8–12 inches
* Smile, talk, and wait. Give them time to respond. The social smile takes a beat.
* Respond to every smile: smile back, say something, make it a two way exchange',
   'Smiling at the ceiling or a pattern on the wall is reflexive, not social. The social smile is specifically triggered by a face. Don''t count random smiles as the milestone.', NULL, 'CDC Developmental Milestones (2024); AAP Autism Screening Guidelines; Johnson et al. (2015), Early Social Smile and ASD Detection',
   NULL, FALSE, TRUE),
  ('social-stranger-anxiety', 'Stranger anxiety emerging — this is healthy', 'social', 'advisory',
   26, 30, 43,
   2, 'Stranger anxiety, the wariness or distress at unfamiliar people, typically emerges between 6 and 10 months. It is a sign of healthy attachment: the baby has formed a strong enough bond with primary caregivers to distinguish them clearly from others. It is not a problem to solve. It is a developmental sign that the attachment system is working.', '* Do not force interaction with strangers or unfamiliar relatives
* Stay in sight when introducing a new person, your presence is the safety signal
* Give the child time to warm up on their own terms',
   'Grandparents and relatives who feel hurt by the baby''s reaction need to understand this is a developmental milestone, not a personal rejection. A few minutes of patient, non pressuring presence usually results in engagement.', 'Complete absence of any stranger wariness by 9 months (universally happy with all strangers) can occasionally be a flag worth noting in the context of other developmental observations.', 'Ainsworth (1967); Bowlby (1969); CDC',
   NULL, FALSE, TRUE),
  ('social-tantrums-peak', 'Tantrum peak — response strategy matters now', 'social', 'advisory',
   78, 91, 156,
   1, 'The peak of tantrum behavior, 18 months to 3 years, is not a discipline problem. It''s a brain development problem. The prefrontal cortex, which governs emotional regulation, won''t be fully developed until the mid 20s. At 18 months, it barely exists. Your child is not defiant; they are neurologically incapable of managing the emotions they''re experiencing. But how you respond now sets patterns that last for years. Specifically: whether the child learns that tantrums are effective strategies or whether they learn that co regulation with a calm adult is available.', '* During a tantrum: stay physically present, stay calm, say little. You''re a co regulator, not a negotiator.
* Never negotiate during a tantrum, it teaches that tantrums are effective tools for getting what they want
* After the tantrum: name what happened and reconnect. "You got really upset when we had to leave the park. That was hard."
* Prevent where possible: tantrums spike with hunger, tiredness, and transitions, manage the environment, not just the behavior',
   'Tantrums do not indicate a difficult child or poor parenting. They are developmentally universal. The research shows that parents who remain calm during tantrums have children who recover faster and tantrum less frequently over time.', 'Tantrums typically peak around age 2 and gradually decline through age 4. If they''re intensifying after age 4 or involving breath holding, self harm, or lasting more than 25 minutes, discuss with your pediatrician.', 'Potegal & Davidson (2003), Tantrums Research; Zelazo et al., Prefrontal Development Research; AAP Bright Futures Behavioral Guidance; FamilyForce Tantrum Playbook',
   'getfamilyforce.com/playbook-tantrum', FALSE, TRUE)
